PACKS_ECE.push(
  { id: "diode", subject: AEC, keys: ["pn junction", "p n junction", "diode", "diodes", "diode characteristics", "forward bias", "reverse bias", "shockley equation", "zener breakdown", "avalanche breakdown", "depletion region", "barrier potential", "knee voltage"], title: "PN junction diode and its characteristics",
    short: "A diode is a PN junction that conducts easily when forward biased and blocks current (apart from a tiny leakage) when reverse biased.",
    points: ["Where P and N meet, a depletion region forms with a built-in barrier potential: about 0.7 V for silicon and 0.3 V for germanium.", "Forward bias: current is almost zero until the applied voltage reaches the knee (cut-in) voltage, then it rises exponentially.", "Reverse bias: only a very small reverse saturation current Is flows. It roughly doubles for every 10 °C rise in temperature.", "Breakdown: Zener breakdown (below about 5 V, field emission in heavily doped junctions) and avalanche breakdown (above about 7 V, impact ionisation). Between them the effect is a mix of both.", "The forward voltage drop falls by about 2 mV per °C as temperature rises.", "Temperature coefficient of breakdown: Zener (below about 5 V) has a negative coefficient; avalanche (above about 7 V) has a positive coefficient. Around 5.6 V the two cancel, so a 5.6 V Zener is very stable with temperature."],
    formulas: [["Diode equation", "I = Is (e^(V/(n·VT)) − 1)"], ["Thermal voltage", "VT = kT/q ≈ 26 mV at 300 K"], ["Dynamic (ac) resistance", "rd = n·VT / I ≈ 26 mV / I"], ["DC resistance", "RD = V / I"]],
    example: { title: "Diode with Is = 10⁻¹² A, n = 1, forward voltage 0.6 V at 300 K", text: "I = 10⁻¹² (e^(0.6/0.026) − 1)\ne^(23.08) ≈ 1.05 × 10¹⁰\nI ≈ 10.5 mA\nrd = 26 mV / 10.5 mA ≈ 2.5 Ω" },
    exam: "A PN junction diode is a two-terminal device formed by joining p-type and n-type semiconductors. In forward bias it conducts with a knee voltage of about 0.7 V (Si) and 0.3 V (Ge); in reverse bias only the small reverse saturation current flows until breakdown. Its current is given by the diode equation I = Is(e^(V/nVT) − 1), where VT = kT/q ≈ 26 mV at room temperature.",
    mistakes: ["Saying the reverse current is exactly zero. A small leakage current Is always flows.", "Mixing up Zener (low-voltage, field emission) and avalanche (high-voltage, impact ionisation) breakdown.", "Forgetting that Is and the knee voltage change with temperature."],
    uses: [["Power adapters and chargers", "Diodes in rectifiers convert AC from the wall into DC."], ["Protection circuits", "A diode across a relay coil absorbs the voltage spike."], ["Signal detection and LEDs", "Diodes detect AM radio signals, and LEDs are diodes that give light."]], related: ["Rectifiers", "Zener diode voltage regulator", "Clippers and clampers"], diagrams: ["diodeIV"] },
  { id: "rectifier", subject: AEC, keys: ["rectifier", "rectifiers", "half wave rectifier", "full wave rectifier", "bridge rectifier", "ripple factor", "ripple", "peak inverse voltage", "piv", "capacitor filter", "rectifier efficiency", "center tapped rectifier"], title: "Rectifiers and filters",
    short: "A rectifier converts AC into pulsating DC using diodes. A filter (usually a capacitor) smooths the pulses into a steadier DC level.",
    points: ["Half-wave: one diode, conducts for half the cycle. Full-wave centre-tap: two diodes and a centre-tapped transformer. Bridge: four diodes, no centre tap needed.", "Full-wave gives twice the ripple frequency (2f), a higher DC output and lower ripple than half-wave.", "PIV (peak inverse voltage) is the largest reverse voltage a diode must withstand: Vm for half-wave and bridge, 2Vm for the centre-tap circuit.", "A capacitor filter charges to the peak and discharges slowly through the load. A bigger capacitor or a larger load resistance gives less ripple.", "In a bridge rectifier two diodes conduct in each half cycle, so two diode drops are lost."],
    formulas: [["Half-wave Vdc", "Vm / π  (= 0.318 Vm)"], ["Half-wave Vrms", "Vm / 2"], ["Half-wave ripple factor", "γ = 1.21,  η max = 40.6%"], ["Full-wave Vdc", "2Vm / π  (= 0.636 Vm)"], ["Full-wave Vrms", "Vm / √2"], ["Full-wave ripple factor", "γ = 0.48,  η max = 81.2%"], ["Ripple factor", "γ = Vrms(ac) / Vdc"], ["Ripple voltage (peak-to-peak)", "Vr = Idc / (f·C) half-wave,  Idc / (2f·C) full-wave"], ["Capacitor filter, full-wave", "γ = 1 / (4√3 · f · RL · C)  (triangular-ripple approximation)"], ["Capacitor filter, half-wave", "γ = 1 / (2√3 · f · RL · C)"]],
    example: { title: "Transformer secondary peak Vm = 10 V (ideal diodes)", text: "Half-wave: Vdc = 10/π = 3.18 V\nFull-wave: Vdc = 2 × 10/π = 6.37 V\nRipple frequency: half-wave f = 50 Hz, full-wave 2f = 100 Hz\nPIV of the bridge diodes = 10 V" },
    exam: "A rectifier converts alternating current into unidirectional current. For a half-wave rectifier, Vdc = Vm/π, Vrms = Vm/2, ripple factor = 1.21 and maximum efficiency = 40.6%. For a full-wave rectifier, Vdc = 2Vm/π, Vrms = Vm/√2, ripple factor = 0.48 and efficiency = 81.2%. The PIV is Vm for the bridge and 2Vm for the centre-tapped circuit.",
    mistakes: ["Using Vm/π for a full-wave rectifier. The correct value is 2Vm/π.", "Forgetting the 2Vm PIV of the centre-tapped rectifier.", "Forgetting that a bridge rectifier has two diode drops in the conducting path."],
    uses: [["Mobile phone chargers", "A bridge rectifier plus a capacitor gives the DC for the charger."], ["Power supplies for lab equipment", "Rectifier, filter and regulator form the standard DC supply."], ["Radio demodulators", "A half-wave rectifier with a capacitor detects AM signals."]], related: ["PN junction diode and its characteristics", "Zener diode voltage regulator", "Voltage regulators and power supplies"], diagrams: ["halfwave", "bridge"] },
  { id: "zenerreg", subject: AEC, keys: ["zener regulator", "zener diode regulator", "zener voltage regulator", "shunt regulator", "line regulation", "load regulation", "voltage regulation zener"], title: "Zener diode voltage regulator",
    short: "A Zener diode operated in reverse breakdown holds its voltage almost constant. Placed across the load with a series resistor, it keeps the load voltage steady.",
    points: ["The Zener must stay in breakdown: its current must be at least Iz(min) and not more than Iz(max).", "The series resistor Rs drops the extra voltage and limits the current.", "Line regulation: how well Vout stays constant when Vin changes. Load regulation: how well Vout stays constant when the load current changes.", "Zener power rating: Pz = Vz × Iz(max). Choose Rs so the Zener never exceeds this."],
    steps: ["Find the load current IL = Vz / RL.", "Choose Zener current Iz (above Iz(min)).", "Compute Rs = (Vin − Vz) / (Iz + IL).", "Check the worst case: Vin maximum with the load removed must not exceed the Zener power rating."],
    formulas: [["Series resistor", "Rs = (Vin − Vz) / (Iz + IL)"], ["Zener power", "Pz = Vz · Iz"], ["Load regulation", "(V(no load) − V(full load)) / V(full load) × 100%"]],
    example: { title: "Vin = 12 V, Vz = 5.6 V, IL = 20 mA, Iz = 10 mA", text: "Rs = (12 − 5.6) / (10 mA + 20 mA)\nRs = 6.4 / 0.03 = 213 Ω → use 220 Ω\nPz at no load = 5.6 V × 29 mA ≈ 0.16 W" },
    exam: "A Zener diode regulator consists of a Zener diode connected in reverse across the load with a series resistor Rs. In breakdown the Zener voltage stays almost constant at Vz, so the output voltage is regulated. Rs = (Vin − Vz)/(Iz + IL). The regulator works only if Iz stays between Iz(min) and Iz(max).",
    mistakes: ["Connecting the Zener in forward bias. It must be reverse biased for regulation.", "Forgetting the Zener current when calculating Rs.", "Not checking the no-load condition, when the whole current flows in the Zener."],
    uses: [["Reference voltage in small circuits", "A Zener gives a steady reference for sensors and ADCs."], ["Overvoltage protection", "It clamps spikes to a safe value."], ["Simple low-current supplies", "Used where an IC regulator is too big or costly."]], related: ["PN junction diode and its characteristics", "Rectifiers and filters", "Voltage regulators and power supplies"], diagrams: ["zenerreg"] },
  { id: "clipclamp", subject: AEC, keys: ["clipper", "clippers", "clamper", "clampers", "clipping circuit", "clamping circuit", "limiter", "dc restorer"], title: "Clippers and clampers",
    short: "A clipper cuts off the part of a waveform above or below a chosen level. A clamper shifts the whole waveform up or down without changing its shape.",
    points: ["Series clipper: the diode is in series with the output. Shunt (parallel) clipper: the diode is across the output.", "Positive clipper removes the positive part, negative clipper the negative part. A reference battery changes the clipping level.", "Clamper = capacitor + diode (+ battery). The capacitor charges to the peak value and acts like a DC battery added to the signal.", "A positive clamper shifts the waveform up so its negative peak sits at 0 V (plus any reference). A negative clamper shifts it down.", "The time constant RC of a clamper must be much larger than the signal period."],
    formulas: [["Clamper shift", "Vout = Vin + Vc  (Vc ≈ Vm for an ideal clamp)"], ["Clamper condition", "RC ≫ T (the signal period)"]],
    example: { title: "5 V peak sine wave into an ideal positive clamper", text: "The capacitor charges to about 5 V.\nOutput = input + 5 V\nThe output swings from 0 V to +10 V." },
    exam: "A clipper is a circuit that removes a portion of the input signal above or below a certain level without distorting the remaining part. A clamper adds a DC level to the input signal and is also called a DC restorer. It uses a capacitor, a diode and sometimes a battery; the time constant must be large compared with the signal period.",
    mistakes: ["Mixing up clipping (cuts part of the signal) with clamping (shifts the whole signal).", "Using a small RC for a clamper, so the capacitor discharges and the output droops.", "Forgetting the 0.7 V diode drop in a practical circuit."],
    uses: [["Audio and radio protection", "Clippers stop large spikes from damaging an amplifier input."], ["TV and display circuits", "Clampers restore the DC level of the video signal."], ["Waveform shaping", "Clippers turn a sine wave into a square-like wave."]], related: ["PN junction diode and its characteristics", "Rectifiers and filters"], diagrams: [] },
  { id: "bjt", subject: AEC, keys: ["bjt", "bipolar junction transistor", "transistor configurations", "common emitter", "common base", "common collector", "emitter follower", "transistor alpha beta", "transistor regions", "bjt characteristics", "input characteristics", "output characteristics"], title: "BJT: regions, configurations and characteristics",
    short: "A bipolar junction transistor (BJT) is a three-terminal device (emitter, base, collector) in which a small base current controls a much larger collector current.",
    points: ["NPN and PNP types. The emitter is heavily doped, the base is thin and lightly doped, and the collector is moderately doped.", "Active region: base–emitter junction forward biased, base–collector junction reverse biased (used for amplifiers). Saturation: both forward biased (switch ON). Cutoff: both reverse biased (switch OFF).", "IE = IB + IC. Current gains: α = IC/IE (just below 1) and β = IC/IB (typically 50–300).", "Common emitter (CE): high current, voltage and power gain, 180° phase shift. Common base (CB): current gain < 1, no phase shift, low input resistance. Common collector (CC, emitter follower): voltage gain ≈ 1, high input and low output resistance.", "Early effect: the output curves slope slightly because the base width shrinks as VCE rises."],
    formulas: [["Emitter current", "IE = IB + IC"], ["Alpha", "α = IC / IE"], ["Beta", "β = IC / IB"], ["β from α", "β = α / (1 − α)"], ["α from β", "α = β / (1 + β)"], ["With leakage", "IC = βIB + (1 + β)ICBO"]],
    example: { title: "A transistor has IB = 20 µA and β = 100", text: "IC = β IB = 100 × 20 µA = 2 mA\nIE = IB + IC = 2.02 mA\nα = IC / IE = 2 / 2.02 = 0.99" },
    exam: "A BJT is a current-controlled device with three regions: emitter, base and collector. In the active region the emitter–base junction is forward biased and the collector–base junction is reverse biased. IE = IB + IC, α = IC/IE and β = IC/IB, with β = α/(1 − α). The CE configuration gives high current and voltage gain with a 180° phase shift; the CC configuration is used as a buffer.",
    mistakes: ["Mixing up the junction bias conditions for active and saturation regions.", "Saying β is a fixed constant. It changes with temperature and collector current.", "Forgetting the 180° phase shift of the CE amplifier."],
    uses: [["Audio amplifiers", "CE stages boost the signal from a microphone."], ["Switches and drivers", "A BJT in saturation drives LEDs, relays and motors."], ["Buffers", "An emitter follower connects a high-impedance source to a low-impedance load."]], related: ["BJT biasing and the Q point", "BJT small-signal amplifier (CE)", "MOSFET and JFET"], diagrams: ["bjtchar"] },
  { id: "bjtbias", subject: AEC, keys: ["biasing", "bjt biasing", "transistor biasing", "q point", "operating point", "load line", "dc load line", "fixed bias", "voltage divider bias", "self bias", "stability factor", "thermal runaway", "emitter bias"], title: "BJT biasing and the Q point",
    short: "Biasing sets the DC operating point (Q point) of a transistor in the middle of the active region so it can amplify without distortion.",
    points: ["The Q point is the DC values (IC, VCE) with no signal. The DC load line joins the points VCE = VCC (IC = 0) and IC = VCC/(RC + RE) (VCE = 0).", "Fixed bias is simple but has poor stability because IC changes strongly with β and temperature (stability factor S = 1 + β).", "Voltage-divider bias with an emitter resistor is the most stable and the most used. A good design has S ≈ 1 + RTH/RE, which is small.", "Thermal runaway: more temperature → more current → more heating. Emitter resistance and good biasing prevent it.", "For the largest undistorted swing, place the Q point near the middle of the load line (VCE ≈ VCC/2)."],
    steps: ["Find the Thevenin equivalent of the divider: VTH = VCC·R2/(R1+R2), RTH = R1‖R2.", "Write the base loop: VTH = IB·RTH + VBE + IE·RE, with IE = (1 + β) IB.", "Solve IB, then IC = β IB.", "VCE = VCC − IC·RC − IE·RE. Check it lies in the active region."],
    formulas: [["Fixed bias", "IB = (VCC − VBE) / RB,  IC = β IB"], ["Thevenin", "VTH = VCC R2/(R1 + R2),  RTH = R1 ‖ R2"], ["Base current", "IB = (VTH − VBE) / (RTH + (1 + β) RE)"], ["Collector–emitter", "VCE = VCC − IC RC − IE RE"], ["Stability factors", "S = 1 + β (fixed),  S ≈ 1 + RTH/RE (divider)"]],
    example: { title: "VCC = 12 V, R1 = 10 kΩ, R2 = 2.2 kΩ, RC = 4 kΩ, RE = 1 kΩ, β = 100, VBE = 0.7 V", text: "VTH = 12 × 2.2 / 12.2 = 2.16 V\nRTH = 10k ‖ 2.2k = 1.8 kΩ\nIB = (2.16 − 0.7) / (1.8k + 101 × 1k) = 14.2 µA\nIC = 100 × 14.2 µA = 1.42 mA\nVCE = 12 − 1.42m × 4k − 1.44m × 1k = 4.88 V (active)" },
    exam: "Biasing is the process of fixing the DC operating point of a transistor so that it works in the active region. The Q point is the intersection of the DC load line and the transistor characteristic. The voltage-divider bias circuit provides the best stability, with stability factor S ≈ 1 + RTH/RE. The collector-emitter voltage is VCE = VCC − ICRC − IERE.",
    mistakes: ["Putting the Q point near saturation or cutoff, which clips the signal.", "Forgetting the (1 + β)RE term when finding IB.", "Using the same bias equations for AC analysis. Capacitors are open in DC and short in AC."],
    uses: [["Every transistor amplifier", "Audio, radio and sensor amplifiers all need stable biasing."], ["Circuits that work over temperature", "Voltage-divider bias keeps gain steady from cold to hot."]], related: ["BJT: regions, configurations and characteristics", "BJT small-signal amplifier (CE)", "Power amplifiers (Class A, B, AB, C)"], diagrams: ["bjtbias", "bjtchar"] },
  { id: "ceamp", subject: AEC, keys: ["small signal amplifier", "hybrid pi", "hybrid pi model", "h parameters", "ce amplifier", "common emitter amplifier", "transconductance", "voltage gain of ce", "ac analysis", "small signal model", "r pi", "gm"], title: "BJT small-signal amplifier (CE)",
    short: "For small AC signals the transistor is replaced by a simple linear model (hybrid-π). From it we find the voltage gain, input resistance and output resistance of the amplifier.",
    points: ["For AC analysis: DC sources become ground, large coupling and bypass capacitors become short circuits.", "Hybrid-π parameters: gm = IC/VT, rπ = β/gm, ro = VA/IC (VA is the Early voltage).", "CE amplifier with the emitter bypassed: Av = −gm (RC ‖ RL ‖ ro), Rin = R1 ‖ R2 ‖ rπ, Rout ≈ RC.", "With an unbypassed emitter resistor RE: Av ≈ −RC/RE (the gain becomes stable but smaller) and Rin(base) = rπ + (1 + β)RE.", "Emitter follower: voltage gain slightly below 1, high input resistance and low output resistance. It is used as a buffer.", "h-parameters (hie, hfe, hre, hoe) give the same analysis in another form: hie ≈ rπ and hfe ≈ β."],
    formulas: [["Transconductance", "gm = IC / VT ≈ IC / 26 mV"], ["Input resistance", "rπ = β / gm"], ["CE voltage gain", "Av = −gm (RC ‖ RL)"], ["With RE unbypassed", "Av ≈ −RC / RE"], ["Emitter follower", "Av ≈ 1,  Rout ≈ re = VT / IE"]],
    example: { title: "IC = 1 mA, β = 100, RC = 4 kΩ, RL → ∞, RE bypassed", text: "gm = 1 mA / 26 mV = 38.5 mS\nrπ = 100 / 38.5 mS = 2.6 kΩ\nAv = −gm RC = −38.5 mS × 4 kΩ = −154" },
    exam: "In the small-signal analysis of a CE amplifier the transistor is replaced by its hybrid-π model with gm = IC/VT, rπ = β/gm and ro = VA/IC. The voltage gain is Av = −gm(RC‖RL), the input resistance is rπ (in parallel with the bias resistors), and the output resistance is approximately RC. The output is 180° out of phase with the input.",
    mistakes: ["Using DC values (VCC) in the AC model. All DC sources are treated as ground.", "Forgetting the minus sign (phase inversion) in Av.", "Using IC in amperes with VT in millivolts without converting units."],
    uses: [["Preamplifiers for microphones and sensors", "CE stages boost weak signals."], ["Radio receivers", "Tuned CE stages amplify the wanted station."], ["Buffers between circuits", "An emitter follower stops the load from affecting the source."]], related: ["BJT biasing and the Q point", "Feedback amplifiers", "Frequency response of amplifiers"], diagrams: ["ceamp"] },
  { id: "fet", subject: AEC, keys: ["mosfet", "jfet", "fet", "field effect transistor", "enhancement mosfet", "depletion mosfet", "pinch off voltage", "idss", "threshold voltage", "triode region", "saturation region fet", "nmos", "pmos", "cmos inverter"], title: "MOSFET and JFET",
    short: "A field-effect transistor (FET) controls the current between source and drain with the voltage on its gate. It has a very high input resistance because almost no gate current flows.",
    points: ["JFET: a depletion-mode device. The gate–channel junction is reverse biased. Pinch-off voltage VP and saturation current IDSS describe it.", "MOSFET: the gate is insulated by an oxide layer. Enhancement type needs VGS > Vt to form a channel. Depletion type already has a channel.", "Regions (n-channel enhancement): cutoff (VGS < Vt), triode or ohmic (VDS < VGS − Vt) and saturation (VDS ≥ VGS − Vt). Amplifiers work in saturation.", "A MOSFET in the triode region acts like a voltage-controlled resistor; in cutoff and triode it acts as a switch.", "Common-source amplifier: Av = −gm RD (with RL: −gm (RD ‖ RL)), phase inverted, very high input resistance."],
    formulas: [["JFET", "ID = IDSS (1 − VGS/VP)²"], ["MOSFET triode", "ID = k [(VGS − Vt) VDS − VDS²/2]"], ["MOSFET saturation", "ID = (k/2)(VGS − Vt)²"], ["Transconductance", "gm = k (VGS − Vt) = 2 ID / (VGS − Vt)"], ["Process constant", "k = µn Cox (W/L)"]],
    example: { title: "NMOS: k = 2 mA/V², Vt = 1 V, VGS = 3 V (saturation)", text: "ID = (k/2)(VGS − Vt)² = 1 mA/V² × (2 V)² = 4 mA\ngm = k (VGS − Vt) = 2 mA/V² × 2 V = 4 mS" },
    exam: "A MOSFET is a voltage-controlled device whose drain current is controlled by the gate–source voltage. In the saturation region, ID = (k/2)(VGS − Vt)², and gm = k(VGS − Vt). The gate is insulated, so the input resistance is extremely high. The enhancement MOSFET conducts only when VGS exceeds the threshold voltage Vt.",
    mistakes: ["Using the saturation equation in the triode region.", "Mixing up enhancement and depletion types.", "Saying a MOSFET draws no current at all. The gate current is only negligible in DC."],
    uses: [["Processors and memory chips", "Billions of MOSFETs form the logic gates (CMOS)."], ["Power switches", "Power MOSFETs switch motors and DC–DC converters efficiently."], ["Amplifiers with high input impedance", "FET input stages suit sensors and microphones."]], related: ["BJT: regions, configurations and characteristics", "Logic families (TTL, CMOS, ECL)", "Frequency response of amplifiers"], diagrams: ["mosfet"] },
  { id: "feedbackamp", subject: AEC, keys: ["feedback amplifier", "feedback amplifiers", "negative feedback", "positive feedback", "voltage series feedback", "current series feedback", "voltage shunt feedback", "current shunt feedback", "feedback topologies", "loop gain", "desensitivity"], title: "Feedback amplifiers",
    short: "In a feedback amplifier a fraction β of the output is returned to the input. Negative feedback lowers the gain but improves stability, bandwidth and distortion.",
    points: ["Gain with feedback: Af = A / (1 + Aβ) for negative feedback. The factor 1 + Aβ is called the desensitivity (or amount of feedback). Aβ is the loop gain.", "Negative feedback: makes the gain more stable, extends the bandwidth by (1 + Aβ), and reduces distortion and noise by (1 + Aβ).", "Four topologies: voltage-series (voltage amplifier), current-series (transconductance), current-shunt (current amplifier) and voltage-shunt (transresistance).", "Series mixing increases the input resistance. Shunt mixing decreases it. Voltage sampling decreases the output resistance. Current sampling increases it.", "For large loop gain (Aβ ≫ 1), Af ≈ 1/β, so the gain depends only on the feedback network."],
    formulas: [["Closed-loop gain", "Af = A / (1 + Aβ)"], ["Bandwidth", "BWf = BW (1 + Aβ)"], ["Gain sensitivity", "dAf/Af = (1/(1 + Aβ)) · dA/A"], ["Input resistance (series)", "Rif = Ri (1 + Aβ)"], ["Input resistance (shunt)", "Rif = Ri / (1 + Aβ)"], ["Large loop gain", "Af ≈ 1/β"]],
    example: { title: "A = 1000, β = 0.1", text: "Af = 1000 / (1 + 1000 × 0.1) = 1000 / 101 = 9.9 ≈ 10 (almost 1/β)\nIf A drops by 10% to 900:\nAf = 900 / 91 = 9.89 — the gain barely changes." },
    exam: "Feedback is the process of returning a part of the output signal to the input. In negative feedback the gain is Af = A/(1 + Aβ). Negative feedback reduces the gain but increases its stability, increases bandwidth, reduces noise and distortion and modifies the input and output resistances depending on the topology. The four topologies are voltage-series, voltage-shunt, current-series and current-shunt.",
    mistakes: ["Using Af = A(1 + Aβ). It is A/(1 + Aβ).", "Mixing up which topology raises or lowers the input and output resistance.", "Forgetting that too much phase shift can turn negative feedback into positive feedback and cause oscillation."],
    uses: [["Op-amp circuits", "Every inverting and non-inverting amplifier relies on negative feedback."], ["High-fidelity audio amplifiers", "Feedback lowers distortion."], ["Voltage regulators", "A feedback loop keeps the output voltage steady."]], related: ["Oscillators", "Operational amplifier circuits", "BJT small-signal amplifier (CE)"], diagrams: ["fbloop"] },
  { id: "oscillator", subject: AEC, keys: ["oscillator", "oscillators", "barkhausen criterion", "rc phase shift oscillator", "wien bridge oscillator", "colpitts oscillator", "hartley oscillator", "crystal oscillator", "lc oscillator", "sinusoidal oscillator"], title: "Oscillators",
    short: "An oscillator is a circuit that produces a continuous AC output without any input signal. It uses an amplifier with positive feedback.",
    points: ["Barkhausen criterion: the loop gain |Aβ| must be 1 and the total phase shift around the loop must be 0° (or 360°).", "To start oscillation the loop gain must be slightly above 1; the amplitude then settles by non-linearity.", "RC phase-shift oscillator: three RC sections give 180° and the amplifier gives another 180°. It needs a gain of at least 29.", "Wien bridge oscillator: a series-parallel RC network gives 0° phase at f = 1/(2πRC), with feedback factor 1/3, so the amplifier gain must be exactly 3 in steady state (slightly above 3 to start the oscillation).", "LC oscillators: Colpitts (two capacitors) and Hartley (two inductors) are used for radio frequencies.", "Crystal oscillator: a quartz crystal gives a very stable frequency because of its high Q and its series and parallel resonance."],
    formulas: [["Barkhausen", "|A β| = 1,  phase = 0° or 360°"], ["RC phase shift", "f = 1 / (2π √6 · RC),  |A| ≥ 29"], ["Wien bridge", "f = 1 / (2π RC),  |A| = 3 (a little above 3 to start)"], ["Colpitts", "f = 1 / (2π √(L · Ceq)),  Ceq = C1C2 / (C1 + C2)"], ["Hartley", "f = 1 / (2π √(Leq · C)),  Leq = L1 + L2 + 2M"]],
    example: { title: "Wien bridge oscillator with R = 10 kΩ and C = 16 nF", text: "f = 1 / (2π × 10 000 × 16 × 10⁻⁹)\nf = 1 / (1.005 × 10⁻³) ≈ 995 Hz ≈ 1 kHz\nThe amplifier gain must be 3, for example Rf = 2R1 in a non-inverting op-amp stage." },
    exam: "An oscillator is an electronic circuit that generates a periodic waveform without an external input signal. It works on positive feedback with the Barkhausen criterion: the magnitude of the loop gain |Aβ| must be unity and the phase shift around the loop must be zero or an integral multiple of 360°. The Wien bridge oscillator has f = 1/(2πRC) and requires gain 3; the RC phase-shift oscillator has f = 1/(2π√6RC) and requires gain 29.",
    mistakes: ["Saying the loop gain should be less than 1. It must be at least 1 to start and exactly 1 in steady state.", "Using f = 1/(2πRC) for the RC phase-shift oscillator. It has the extra √6.", "Mixing up Colpitts (capacitor tap) and Hartley (inductor tap)."],
    uses: [["Clocks in every digital device", "Crystal oscillators give the clock for phones and computers."], ["Radio transmitters", "LC oscillators set the carrier frequency."], ["Test equipment", "Function generators use Wien bridge or RC oscillators."]], related: ["Feedback amplifiers", "555 timer and multivibrators", "Operational amplifier circuits"], diagrams: ["fbloop"] },
  { id: "opampapp", subject: AEC, keys: ["op amp applications", "op amp circuits", "operational amplifier circuits", "operational amplifier applications", "inverting amplifier circuit", "non inverting amplifier circuit", "summing amplifier", "difference amplifier", "integrator", "differentiator", "op amp comparator", "voltage comparator", "schmitt trigger", "instrumentation amplifier", "slew rate", "voltage follower", "adder using op amp"], title: "Operational amplifier circuits",
    short: "With negative feedback an op-amp makes precise amplifiers, adders, integrators, differentiators and comparators. The gain depends only on the external resistors and capacitors.",
    points: ["Ideal op-amp: infinite gain, infinite input resistance, zero output resistance, infinite bandwidth, zero offset. With negative feedback the two inputs sit at the same voltage (virtual short).", "Inverting amplifier: Av = −Rf/Rin. The inverting input is a virtual ground.", "Non-inverting amplifier: Av = 1 + Rf/Rin. A voltage follower is the special case with gain 1 and gives very high input resistance.", "Summing amplifier: Vout = −Rf (V1/R1 + V2/R2 + …). Difference amplifier: Vout = (Rf/R1)(V2 − V1) when the resistors are matched.", "Integrator: Vout = −(1/RC)∫Vin dt. Differentiator: Vout = −RC dVin/dt.", "Comparator: no feedback, output saturates at the positive or negative supply. A Schmitt trigger adds positive feedback for hysteresis and noise immunity.", "Real op-amps: slew rate SR (maximum dVo/dt), gain–bandwidth product (constant), input offset voltage and CMRR limit the performance."],
    formulas: [["Inverting", "Av = −Rf / Rin"], ["Non-inverting", "Av = 1 + Rf / Rin"], ["Summer", "Vout = −Rf (V1/R1 + V2/R2)"], ["Integrator", "Vout = −(1/RC) ∫ Vin dt"], ["Differentiator", "Vout = −RC · dVin/dt"], ["Slew rate limit", "fmax = SR / (2π Vp)"], ["Bandwidth", "BW = GBW / |Av|"]],
    example: { title: "Inverting amplifier with Rin = 10 kΩ, Rf = 100 kΩ and Vin = 0.2 V", text: "Av = −100k / 10k = −10\nVout = −10 × 0.2 V = −2 V\nA 741 op-amp has GBW ≈ 1 MHz, so BW = 1 MHz / 10 = 100 kHz." },
    exam: "An operational amplifier is a high-gain direct-coupled differential amplifier. With negative feedback, the inverting amplifier has gain −Rf/Rin and the non-inverting amplifier has gain 1 + Rf/Rin. An integrator gives Vout = −(1/RC)∫Vin dt and a summing amplifier gives Vout = −Rf(V1/R1 + V2/R2). The slew rate is the maximum rate of change of the output voltage.",
    mistakes: ["Forgetting the minus sign in the inverting configuration.", "Using the ideal gain formula at frequencies close to the gain–bandwidth limit.", "Applying the virtual-ground idea to a comparator, which has no negative feedback."],
    uses: [["Audio mixers", "Summing amplifiers add several microphone signals."], ["Sensor signal conditioning", "Instrumentation amplifiers boost tiny bridge sensor voltages."], ["Filters, timers and ADCs", "Op-amps are the building block of active filters and converters."]], related: ["Operational amplifier (op-amp)", "Differential amplifier and CMRR", "Feedback amplifiers"], diagrams: ["opinv", "opnon", "opint", "opsum"] },
  { id: "diffamp", subject: AEC, keys: ["differential amplifier", "differential amplifier cmrr", "cmrr", "common mode rejection ratio", "common mode gain", "differential gain", "long tailed pair", "tail current source", "differential pair"], title: "Differential amplifier and CMRR",
    short: "A differential amplifier amplifies the difference between two inputs and rejects the signal common to both. The ability to reject the common signal is the CMRR.",
    points: ["Output: Vo = Ad·Vd + Ac·Vc, where Vd = V1 − V2 (differential input) and Vc = (V1 + V2)/2 (common-mode input).", "Differential gain Ad should be large and common-mode gain Ac should be as small as possible.", "CMRR = |Ad / Ac|, usually given in dB: CMRR(dB) = 20 log₁₀ |Ad / Ac|.", "A BJT differential pair shares a tail current IEE, so each transistor carries about IEE/2. A current source in the tail gives a very high CMRR.", "For a BJT pair with double-ended output: Ad = gm RC. The differential input resistance is 2rπ.", "Used at the input of every op-amp, so noise and interference picked up equally on both lines (common-mode) are rejected."],
    formulas: [["Output", "Vo = Ad Vd + Ac Vc"], ["CMRR", "ρ = |Ad / Ac|"], ["CMRR in dB", "20 log₁₀ (Ad / Ac)"], ["BJT pair", "Ad = gm RC,  Rid = 2 rπ"]],
    example: { title: "Ad = 1000 and Ac = 0.1", text: "CMRR = 1000 / 0.1 = 10 000\nCMRR(dB) = 20 log₁₀(10 000) = 80 dB" },
    exam: "A differential amplifier amplifies the difference between two input signals and suppresses the signal that is common to both inputs. The output is Vo = AdVd + AcVc. The common-mode rejection ratio is CMRR = |Ad/Ac| and, in decibels, 20 log|Ad/Ac|. A higher CMRR means better rejection of noise and interference.",
    mistakes: ["Defining Vc as the difference. It is the average (V1 + V2)/2.", "Writing CMRR in dB as 10 log. For voltage ratios it is 20 log.", "Forgetting that the tail current source is what gives a high CMRR."],
    uses: [["ECG and EEG machines", "Tiny heart signals are amplified while mains hum is rejected."], ["Op-amp input stage", "Every op-amp starts with a differential pair."], ["Long cable links", "Differential signalling cancels noise picked up along the cable."]], related: ["Operational amplifier circuits", "BJT small-signal amplifier (CE)", "Feedback amplifiers"], diagrams: [] },
  { id: "poweramp", subject: AEC, keys: ["power amplifier", "power amplifiers", "class a amplifier", "class b amplifier", "class ab amplifier", "class c amplifier", "push pull amplifier", "crossover distortion", "conduction angle", "amplifier efficiency", "complementary symmetry"], title: "Power amplifiers (Class A, B, AB, C)",
    short: "A power amplifier delivers a large amount of power to a load such as a loudspeaker. Its classes differ in how long the transistor conducts and how efficient it is.",
    points: ["Class A: conducts for 360°. Linear but inefficient: maximum 25% (series-fed) or 50% (transformer-coupled).", "Class B: conducts for 180°. A push-pull pair of transistors handles the two halves. Maximum efficiency π/4 = 78.5%, but there is crossover distortion near zero.", "Class AB: conducts a bit more than 180°. A small bias removes crossover distortion with efficiency between A and B.", "Class C: conducts for less than 180°. Very efficient (above 90%) but very distorted, so it is used with tuned loads in RF transmitters.", "Complementary-symmetry (NPN + PNP) push-pull stages avoid the need for a transformer.", "Heat sinks are needed. Maximum power dissipation in Class B occurs at an output amplitude of about 63.7% of the supply."],
    formulas: [["Efficiency", "η = Pac(out) / Pdc(in)"], ["Class B output power", "Po = Vm² / (2 RL)"], ["Class B dc input", "Pdc = 2 VCC Vm / (π RL)"], ["Class B efficiency", "η = (π/4)(Vm / VCC) → 78.5% max"], ["Class B max dissipation", "PD(max) = 2 VCC² / (π² RL)"]],
    example: { title: "Class B stage: VCC = 12 V, RL = 8 Ω, Vm = 12 V (full swing)", text: "Po = 12² / (2 × 8) = 9 W\nPdc = 2 × 12 × 12 / (π × 8) = 11.46 W\nη = 9 / 11.46 = 78.5%" },
    exam: "A power amplifier is a large-signal amplifier that delivers a large output power to a load. Power amplifiers are classified by conduction angle: Class A (360°), Class B (180°), Class AB (between 180° and 360°) and Class C (less than 180°). The maximum efficiency is 25% for series-fed Class A, 50% for transformer-coupled Class A and 78.5% for Class B.",
    mistakes: ["Giving 78.5% as the efficiency of Class A.", "Forgetting that Class B has crossover distortion.", "Treating the efficiency as fixed. It depends on the output swing."],
    uses: [["Speakers and headphone amplifiers", "Class AB gives clean sound at good efficiency."], ["Radio transmitters", "Class C stages with tuned circuits drive the antenna."], ["Motor drives", "Push-pull stages deliver current to motors."]], related: ["BJT biasing and the Q point", "Feedback amplifiers", "Operational amplifier circuits"], diagrams: ["classes"] },
  { id: "t555", subject: AEC, keys: ["555 timer", "ne555", "astable multivibrator", "monostable multivibrator", "bistable multivibrator", "multivibrator", "multivibrators", "timer ic", "555 astable", "555 monostable"], title: "555 timer and multivibrators",
    short: "The 555 is a popular timer IC that can work as a monostable (one pulse) or astable (continuous square wave) multivibrator using a few resistors and a capacitor.",
    points: ["Inside: two comparators (thresholds 2/3 VCC and 1/3 VCC), an SR flip-flop, a discharge transistor and a voltage divider of three equal resistors.", "Monostable: one trigger gives one output pulse of fixed width T = 1.1 R C.", "Astable: no stable state, the output oscillates. The capacitor charges through RA + RB and discharges through RB.", "Bistable (flip-flop): two stable states, changed by trigger pulses. Used in memory and counters.", "The duty cycle of the astable circuit is always above 50% unless a diode is added across RB."],
    formulas: [["Monostable pulse width", "T = 1.1 R C"], ["Astable frequency", "f = 1.44 / ((RA + 2RB) C)"], ["High time", "tH = 0.693 (RA + RB) C"], ["Low time", "tL = 0.693 RB C"], ["Duty cycle", "D = (RA + RB) / (RA + 2RB)"]],
    example: { title: "Astable: RA = 1 kΩ, RB = 10 kΩ, C = 0.1 µF", text: "f = 1.44 / ((1k + 20k) × 0.1 µF) = 1.44 / 2.1 ms ≈ 686 Hz\ntH = 0.693 × 11k × 0.1 µF = 0.76 ms\nDuty cycle = 11 / 21 = 52%" },
    exam: "The 555 timer is an integrated circuit that can be used as a monostable or astable multivibrator. In the monostable mode the pulse width is T = 1.1RC. In the astable mode the frequency is f = 1.44/((RA + 2RB)C) and the duty cycle is (RA + RB)/(RA + 2RB). The internal comparators switch at 2/3 VCC and 1/3 VCC.",
    mistakes: ["Using 1.44 for the monostable pulse width. Monostable uses 1.1.", "Forgetting the 2 in RA + 2RB.", "Mixing up the trigger (1/3 VCC) and threshold (2/3 VCC) levels."],
    uses: [["Blinking LEDs and alarms", "An astable 555 drives LEDs and buzzers."], ["Touch switches and timers", "A monostable gives a delay after a button press."], ["PWM motor and dimmer control", "The duty cycle controls the average power."]], related: ["Oscillators", "Flip-flops (SR, D, JK, T)", "Operational amplifier circuits"], diagrams: ["t555"] },
  { id: "freqresp", subject: AEC, keys: ["frequency response", "frequency response of amplifiers", "bandwidth", "miller effect", "gain bandwidth product", "lower cutoff frequency", "upper cutoff frequency", "half power frequency", "low frequency response", "high frequency response", "bode plot amplifier", "coupling capacitor effect"], title: "Frequency response of amplifiers",
    short: "The gain of an amplifier is not the same at all frequencies. It falls at low frequencies because of coupling and bypass capacitors, and at high frequencies because of internal transistor capacitances.",
    points: ["Midband: capacitors have no effect and the gain is constant at Am.", "Low-frequency cutoff fL: set by the coupling and bypass capacitors, fL = 1 / (2π R C).", "High-frequency cutoff fH: set by the transistor junction capacitances and wiring capacitances, fH = 1 / (2π R C).", "Bandwidth BW = fH − fL ≈ fH when fL ≪ fH. At fL and fH the gain falls to 1/√2 (−3 dB) of the midband gain.", "Miller effect: a capacitance Cμ between input and output of an inverting amplifier looks like a much larger capacitance Cμ(1 + |Av|) at the input. It limits the high-frequency response of CE and CS stages.", "For many amplifiers the gain–bandwidth product (|Av| × BW) is nearly constant."],
    formulas: [["Cutoff frequency", "f = 1 / (2π R C)"], ["−3 dB gain", "|A(fc)| = Am / √2"], ["Bandwidth", "BW = fH − fL"], ["Miller capacitance", "CM = Cμ (1 + |Av|)"], ["Gain–bandwidth", "|Av| · BW ≈ constant"]],
    example: { title: "Coupling capacitor C = 10 µF, input resistance seen R = 2 kΩ", text: "fL = 1 / (2π × 2000 × 10 × 10⁻⁶) = 1 / 0.1257 = 7.96 Hz\nBelow about 8 Hz the gain drops by more than 3 dB." },
    exam: "The frequency response is the plot of amplifier gain versus frequency. The lower cutoff frequency is caused by the coupling and bypass capacitors and the upper cutoff frequency by the internal capacitances of the transistor. The bandwidth is BW = fH − fL, measured between the −3 dB points. The Miller effect multiplies a feedback capacitance by (1 + |Av|) and reduces the high-frequency gain.",
    mistakes: ["Forgetting that the −3 dB point is where the gain is 0.707 of the midband value.", "Ignoring the Miller effect in CE stages.", "Using the same capacitor values for low-frequency and high-frequency analysis."],
    uses: [["Audio amplifier design", "Good low and high cutoffs cover the 20 Hz – 20 kHz hearing range."], ["Oscilloscopes and instruments", "The bandwidth decides the fastest signal that can be measured."], ["Radio and video", "Wide bandwidth is needed for picture detail."]], related: ["BJT small-signal amplifier (CE)", "Feedback amplifiers", "Bode plot (frequency response)"], diagrams: [] },
  { id: "regulator", subject: AEC, keys: ["voltage regulator", "voltage regulators", "power supply", "regulated power supply", "7805", "78xx", "lm317", "series regulator", "linear regulator", "smps", "dc dc converter", "switching regulator"], title: "Voltage regulators and power supplies",
    short: "A regulated DC power supply has four blocks: a transformer, a rectifier, a filter and a regulator. The regulator keeps the output voltage constant when the input or the load changes.",
    points: ["Transformer lowers the voltage, rectifier changes AC to pulsating DC, filter smooths it, regulator holds it steady.", "Series (linear) regulator: a pass transistor controlled by an error amplifier, comparing the output with a reference voltage.", "IC regulators: 78xx gives fixed positive voltages (7805 = +5 V), 79xx gives negative voltages and LM317 is adjustable. They need an input a few volts above the output (dropout voltage).", "Switching regulators (SMPS) switch a transistor on and off at high frequency, giving 80–95% efficiency compared with a linear regulator that wastes the voltage difference as heat.", "Line regulation: change in output for a change in input. Load regulation: change in output from no load to full load."],
    formulas: [["Load regulation", "(VNL − VFL) / VFL × 100%"], ["Line regulation", "ΔVout / ΔVin"], ["Linear regulator efficiency", "η ≈ Vout / Vin"], ["Heat in a linear regulator", "P = (Vin − Vout) × Iload"]],
    example: { title: "7805 regulator with Vin = 12 V and load current 500 mA", text: "Power wasted as heat = (12 − 5) × 0.5 = 3.5 W\nEfficiency ≈ 5 / 12 = 42%\nA heat sink is needed." },
    exam: "A voltage regulator is a circuit that maintains a constant output voltage irrespective of changes in the input voltage or the load current. The regulated power supply consists of a transformer, rectifier, filter and regulator. The performance is measured by line regulation and load regulation. Linear regulators are simple and quiet, while switching regulators are more efficient.",
    mistakes: ["Forgetting the heat dissipated in a linear regulator.", "Using an input voltage below the dropout limit of the IC.", "Mixing up line regulation and load regulation."],
    uses: [["Every electronic gadget", "Phones, routers and laptops contain regulators."], ["Microcontroller boards", "A 5 V or 3.3 V regulator powers the chip."], ["Laboratory power supplies", "Adjustable regulators such as the LM317 set any voltage."]], related: ["Rectifiers and filters", "Zener diode voltage regulator", "Feedback amplifiers"], diagrams: ["zenerreg"] },
);
PACKS_ECE.push(
  { id: "dspsig", subject: DSP, keys: ["discrete time signals", "discrete signals", "unit impulse", "unit step", "dsp basics", "signals and systems", "energy signal", "power signal", "periodic signal", "even and odd signals", "discrete time systems", "signal classification", "elementary signals"], title: "Discrete-time signals and systems",
    short: "A discrete-time signal is a sequence x[n] defined only at integer values of n. DSP processes such sequences with digital hardware or software.",
    points: ["Basic sequences: unit impulse δ[n] (1 at n = 0, otherwise 0), unit step u[n] (1 for n ≥ 0) and the exponential a^n u[n].", "Any signal can be written as a sum of shifted impulses: x[n] = Σ x[k] δ[n − k].", "Operations: time shift x[n − k], time reversal x[−n], scaling and addition.", "Energy signal: finite energy E = Σ|x[n]|². Power signal: finite average power. Periodic signals are power signals.", "A discrete-time sinusoid cos(ω₀n) is periodic only if ω₀/2π is a rational number. Frequency ω is in radians per sample and repeats every 2π.", "System properties: linear, time-invariant, causal (output depends on present and past inputs only), stable (bounded input gives bounded output) and memory/memoryless."],
    formulas: [["Impulse decomposition", "x[n] = Σ x[k] δ[n − k]"], ["Energy", "E = Σ |x[n]|²"], ["Average power", "P = lim (1/(2N + 1)) Σ |x[n]|²"], ["Digital frequency", "ω = 2π f / fs  (radians per sample)"], ["Periodicity", "N = 2π k / ω₀  (smallest integer N)"]],
    example: { title: "Is x[n] = cos(0.2πn) periodic?", text: "ω₀ = 0.2π, so ω₀ / 2π = 0.1 = 1/10 (rational)\nYes: the fundamental period is N = 10 samples." },
    exam: "A discrete-time signal is a function defined only at discrete instants n. The unit impulse δ[n] and unit step u[n] are basic signals, and any sequence can be written as x[n] = Σ x[k]δ[n − k]. A discrete-time system is linear if it obeys superposition, time-invariant if a shift in the input produces the same shift in the output, causal if the output depends only on present and past inputs, and BIBO stable if every bounded input gives a bounded output.",
    mistakes: ["Saying every discrete sinusoid is periodic. It needs ω₀/2π to be rational.", "Mixing up energy and power signals.", "Forgetting that discrete frequencies 2π apart are the same."],
    uses: [["Audio and speech processing", "Sampled sound is a discrete-time signal."], ["Mobile phone communication", "Every call is processed as sequences of numbers."], ["Medical devices", "ECG and EEG are sampled and filtered digitally."]], related: ["Sampling and aliasing", "Convolution and LTI systems", "Z-transform"], diagrams: ["sampling"] },
  { id: "sampling", subject: DSP, keys: ["sampling theorem", "nyquist rate", "nyquist theorem", "nyquist sampling", "aliasing", "anti aliasing filter", "sampling frequency", "reconstruction", "sampling rate", "sampling of signals", "folding frequency"], title: "Sampling theorem and aliasing",
    short: "The sampling theorem says that a band-limited signal can be reconstructed exactly if it is sampled at a rate at least twice its highest frequency.",
    points: ["Nyquist rate = 2 fmax. The sampling frequency must satisfy fs ≥ 2 fmax. Half the sampling frequency, fs/2, is the folding frequency.", "If fs is too low, high frequencies appear as lower frequencies (aliasing) and cannot be separated from real ones.", "A frequency f above fs/2 appears at the alias frequency |f − k·fs|, where k is chosen to bring it into the range 0 to fs/2.", "Practical systems use an analog anti-aliasing low-pass filter before the sampler, and a reconstruction filter after the DAC.", "Ideal reconstruction uses a sinc interpolator; real DACs use a zero-order hold followed by a smoothing filter."],
    formulas: [["Sampling theorem", "fs ≥ 2 fmax"], ["Sampled signal", "x[n] = x(n Ts),  Ts = 1/fs"], ["Alias frequency", "fa = |f − k fs|, with 0 ≤ fa ≤ fs/2"], ["Digital frequency", "ω = 2π f / fs"]],
    example: { title: "A 7 kHz tone is sampled at 10 kHz", text: "fs/2 = 5 kHz, and 7 kHz is above it, so it aliases.\nfa = |7 − 10| = 3 kHz\nThe sample values look exactly like a 3 kHz tone.\nTo avoid aliasing use fs ≥ 14 kHz." },
    exam: "The sampling theorem states that a continuous-time signal band-limited to fmax can be completely recovered from its samples if the sampling frequency fs ≥ 2fmax. The minimum rate 2fmax is the Nyquist rate. If fs < 2fmax, the spectral components overlap and aliasing occurs; it is avoided by using an anti-aliasing low-pass filter before sampling.",
    mistakes: ["Confusing the Nyquist rate (2fmax) with the Nyquist frequency (fs/2).", "Sampling exactly at 2fmax for a sinusoid. At exactly the limit the samples may all be zero.", "Believing a digital filter after sampling can remove aliasing. Once it is in, it cannot be separated."],
    uses: [["CD audio at 44.1 kHz", "Chosen to cover the 20 kHz hearing limit."], ["Phone calls at 8 kHz", "Speech is limited to about 4 kHz."], ["Digital oscilloscopes", "Their sampling rate decides the highest signal they can show."]], related: ["Discrete-time signals and systems", "A/D conversion and quantisation", "Multirate signal processing"], diagrams: ["sampling"] },
  { id: "conv", subject: DSP, keys: ["convolution", "linear convolution", "lti system", "lti systems", "impulse response", "difference equation", "causal system", "bibo stability", "circular convolution", "convolution sum", "linear time invariant"], title: "LTI systems and convolution",
    short: "A linear time-invariant (LTI) system is fully described by its impulse response h[n]. The output for any input is the convolution of the input with h[n].",
    points: ["Convolution sum: y[n] = Σ x[k] h[n − k] = x[n] * h[n].", "Properties: commutative, associative and distributive. Cascade systems multiply (convolve) their impulse responses; parallel systems add them.", "Length: if x has L samples and h has M samples, y has L + M − 1 samples.", "Causal: h[n] = 0 for n < 0. BIBO stable: Σ|h[n]| < ∞.", "FIR systems have a finite-length h[n]; IIR systems have an infinite-length h[n].", "A linear constant-coefficient difference equation describes the same system: Σ a_k y[n − k] = Σ b_k x[n − k]."],
    steps: ["Flip h[k] to get h[−k].", "Shift it by n to get h[n − k].", "Multiply with x[k] sample by sample.", "Add all the products to get y[n].", "Repeat for each n."],
    formulas: [["Convolution", "y[n] = Σ x[k] h[n − k]"], ["Output length", "L + M − 1"], ["Causality", "h[n] = 0 for n < 0"], ["Stability", "Σ |h[n]| < ∞"], ["Frequency domain", "Y(z) = H(z) X(z)"]],
    example: { title: "x[n] = {1, 2, 3} and h[n] = {1, 1}", text: "y[0] = 1×1 = 1\ny[1] = 2×1 + 1×1 = 3\ny[2] = 3×1 + 2×1 = 5\ny[3] = 3×1 = 3\ny[n] = {1, 3, 5, 3}  (length 3 + 2 − 1 = 4)" },
    exam: "An LTI system is characterised by its impulse response h[n]. The response to an input x[n] is given by the convolution sum y[n] = Σ x[k]h[n − k]. The system is causal if h[n] = 0 for n < 0 and BIBO stable if Σ|h[n]| is finite. For two sequences of lengths L and M, the linear convolution has length L + M − 1.",
    mistakes: ["Forgetting to flip h[k] before sliding.", "Getting the output length wrong. It is L + M − 1, not L + M.", "Mixing up circular convolution (same length N) with linear convolution."],
    uses: [["Audio effects", "Reverb is a convolution with the impulse response of a room."], ["Image blur and edge detection", "Image filters are 2D convolutions."], ["Wireless channels", "The channel acts as an LTI system that the receiver must undo."]], related: ["Z-transform", "FIR filters", "DFT and FFT"], diagrams: ["firfilter"] },
  { id: "ztrans", subject: DSP, keys: ["z transform", "ztransform", "z-transform", "region of convergence", "roc", "inverse z transform", "transfer function discrete", "system function", "pole zero plot", "unit circle"], title: "Z-transform",
    short: "The z-transform turns a sequence x[n] into a function X(z) of a complex variable z. It makes difference equations easy to solve and shows stability from the positions of poles.",
    points: ["Definition: X(z) = Σ x[n] z^(−n). It converges only for some values of z, called the region of convergence (ROC).", "Time shift: x[n − k] ↔ z^(−k) X(z). Convolution in time becomes multiplication: Y(z) = H(z)X(z).", "Common pairs: δ[n] ↔ 1; u[n] ↔ 1/(1 − z⁻¹) with |z| > 1; aⁿu[n] ↔ 1/(1 − a z⁻¹) with |z| > |a|.", "A causal sequence has an ROC outside the outermost pole. A left-sided (anti-causal) sequence has an ROC inside the innermost pole.", "A causal system is stable if and only if all poles lie inside the unit circle |z| = 1 (the ROC includes the unit circle).", "Inverse z-transform: partial fractions, power series (long division) or the residue method."],
    formulas: [["Z-transform", "X(z) = Σ x[n] z^(−n)"], ["Delay", "x[n − k] ↔ z^(−k) X(z)"], ["Convolution", "x[n] * h[n] ↔ X(z) H(z)"], ["Exponential", "aⁿ u[n] ↔ 1 / (1 − a z⁻¹),  |z| > |a|"], ["Transfer function", "H(z) = Y(z) / X(z)"], ["Frequency response", "H(e^(jω)) = H(z) at z = e^(jω)"]],
    example: { title: "y[n] = 0.5 y[n − 1] + x[n]", text: "Take the z-transform: Y(z) = 0.5 z⁻¹ Y(z) + X(z)\nH(z) = 1 / (1 − 0.5 z⁻¹) = z / (z − 0.5)\nPole at z = 0.5, inside the unit circle → stable (causal)\nh[n] = (0.5)ⁿ u[n]" },
    exam: "The z-transform of a sequence x[n] is X(z) = Σ x[n]z⁻ⁿ. It converges in a region of convergence. The system function H(z) = Y(z)/X(z) is the z-transform of the impulse response. A causal LTI system is BIBO stable if and only if all the poles of H(z) lie inside the unit circle. The frequency response is obtained by putting z = e^(jω).",
    mistakes: ["Forgetting the ROC. The same X(z) can belong to different sequences with different ROCs.", "Saying poles outside the unit circle give a stable causal system.", "Writing the shift property with z^(+k) for a delay. A delay is z^(−k)."],
    uses: [["Designing digital filters", "Poles and zeros are placed to get the wanted response."], ["Solving difference equations", "Algebra replaces step-by-step recursion."], ["Control of sampled systems", "The z-plane is also used for digital controllers."]], related: ["LTI systems and convolution", "IIR filters", "Frequency response and DTFT"], diagrams: ["pzplot"] },
  { id: "dtft", subject: DSP, keys: ["dtft", "discrete time fourier transform", "frequency response of discrete systems", "dft", "discrete fourier transform", "idft", "twiddle factor", "circular shift", "zero padding", "frequency resolution", "parseval", "fourier transform of sequences", "magnitude and phase response", "group delay"], title: "DTFT and DFT",
    short: "The DTFT shows what frequencies are in a sequence. The DFT is its sampled version, computed at N equally spaced frequencies, and is what computers actually calculate.",
    points: ["DTFT: X(e^(jω)) = Σ x[n] e^(−jωn). It is continuous in ω and periodic with period 2π.", "DFT of an N-point sequence: X[k] = Σ_{n=0}^{N−1} x[n] W_N^(nk), where W_N = e^(−j2π/N) is the twiddle factor. IDFT: x[n] = (1/N) Σ X[k] W_N^(−nk).", "Bin k corresponds to the frequency f = k·fs/N. The frequency resolution is Δf = fs/N. Zero padding gives a smoother-looking spectrum but not better resolution.", "Properties: linearity, circular shift, circular convolution (product of DFTs), symmetry (real input gives conjugate-symmetric DFT) and Parseval: Σ|x[n]|² = (1/N)Σ|X[k]|².", "Linear convolution can be done with the DFT if both sequences are zero-padded to at least L + M − 1 points.", "Group delay τ(ω) = −dφ/dω. A linear-phase system has a constant group delay."],
    formulas: [["DTFT", "X(e^(jω)) = Σ x[n] e^(−jωn)"], ["DFT", "X[k] = Σ x[n] e^(−j2πkn/N)"], ["IDFT", "x[n] = (1/N) Σ X[k] e^(j2πkn/N)"], ["Twiddle factor", "W_N = e^(−j2π/N),  W_N^N = 1"], ["Resolution", "Δf = fs / N"], ["Parseval", "Σ|x[n]|² = (1/N) Σ|X[k]|²"], ["Group delay", "τ(ω) = −dφ(ω)/dω"]],
    example: { title: "4-point DFT of x[n] = {1, 2, 3, 4}", text: "W₄ = e^(−jπ/2) = −j\nX[0] = 1 + 2 + 3 + 4 = 10\nX[1] = 1 + 2(−j) + 3(−1) + 4(j) = −2 + 2j\nX[2] = 1 − 2 + 3 − 4 = −2\nX[3] = 1 + 2(j) + 3(−1) + 4(−j) = −2 − 2j" },
    exam: "The discrete-time Fourier transform of x[n] is X(e^(jω)) = Σ x[n]e^(−jωn), a continuous periodic function of ω. The N-point DFT is X[k] = Σ x[n]W_N^(nk), with W_N = e^(−j2π/N), and gives N samples of the DTFT at ω = 2πk/N. The frequency resolution is fs/N. Multiplication of DFTs corresponds to circular convolution in the time domain.",
    mistakes: ["Forgetting the 1/N in the IDFT.", "Saying zero padding improves the true resolution.", "Using the DFT product for linear convolution without enough zero padding (wrap-around errors)."],
    uses: [["Spectrum analysers and audio equalisers", "The DFT shows which frequencies are present."], ["Wi-Fi and 4G/5G (OFDM)", "Transmitters and receivers are built around the FFT."], ["Vibration and fault detection", "Machine health is checked from frequency peaks."]], related: ["FFT (fast Fourier transform)", "LTI systems and convolution", "Z-transform"], diagrams: ["lpfresp"] },
  { id: "fft", subject: DSP, keys: ["fft", "fast fourier transform", "radix 2", "radix 2 fft", "decimation in time", "decimation in frequency", "butterfly", "bit reversal", "dit fft", "dif fft", "fft algorithm"], title: "FFT (fast Fourier transform)",
    short: "The FFT is a fast way to compute the DFT. For N points, the direct DFT needs N² complex multiplications, but the radix-2 FFT needs only (N/2) log₂N.",
    points: ["Radix-2 FFT needs N to be a power of 2 (N = 2^m). It splits the DFT into two half-size DFTs, again and again, for log₂N stages.", "Decimation-in-time (DIT): the input is in bit-reversed order and the output is in natural order. Decimation-in-frequency (DIF): the input is in natural order and the output is in bit-reversed order.", "The butterfly takes two inputs A and B and gives A + W·B and A − W·B, using one complex multiplication.", "Twiddle factor symmetry: W_N^(k + N/2) = −W_N^k, which is what lets each butterfly make two outputs from one product.", "For N = 8, DIT input order: x[0], x[4], x[2], x[6], x[1], x[5], x[3], x[7]."],
    formulas: [["Direct DFT cost", "N² complex multiplications"], ["Radix-2 FFT cost", "(N/2) log₂ N multiplications,  N log₂ N additions"], ["Stages", "log₂ N"], ["Butterfly", "A' = A + W·B,   B' = A − W·B"], ["Symmetry", "W_N^(k + N/2) = −W_N^k"]],
    example: { title: "4-point DIT FFT of x = {1, 2, 3, 4}", text: "Stage 1 (pairs x[0],x[2] and x[1],x[3]):\n  (1, 3) → 1 + 3 = 4,  1 − 3 = −2\n  (2, 4) → 2 + 4 = 6,  2 − 4 = −2\nStage 2 (W₄⁰ = 1, W₄¹ = −j):\n  X[0] = 4 + 6 = 10,   X[2] = 4 − 6 = −2\n  X[1] = −2 + (−j)(−2) = −2 + 2j\n  X[3] = −2 − (−j)(−2) = −2 − 2j\nFor N = 1024: direct = 1 048 576, FFT = 5 120 multiplications (about 200 times fewer)." },
    exam: "The fast Fourier transform is an efficient algorithm for computing the DFT. The radix-2 algorithm reduces the number of complex multiplications from N² to (N/2)log₂N by splitting an N-point DFT into two N/2-point DFTs repeatedly. In the decimation-in-time algorithm the input is shuffled in bit-reversed order and each butterfly computes A + WB and A − WB.",
    mistakes: ["Writing the FFT cost as N log N multiplications. It is (N/2) log₂N complex multiplications.", "Forgetting the bit-reversed order of the input (DIT) or output (DIF).", "Using the radix-2 algorithm when N is not a power of 2 without zero padding."],
    uses: [["Wi-Fi, 4G and 5G", "OFDM modems run FFTs thousands of times per second."], ["Audio and music apps", "Spectrum displays and pitch detection."], ["Medical imaging (MRI)", "Images are reconstructed using the FFT."]], related: ["DTFT and DFT", "LTI systems and convolution", "FIR filters"], diagrams: ["butterfly"] },
  { id: "fir", subject: DSP, keys: ["fir filter", "fir filters", "fir filter design", "window method", "window function", "hamming window", "hanning window", "blackman window", "rectangular window", "linear phase", "gibbs phenomenon", "finite impulse response", "kaiser window"], title: "FIR filters and window design",
    short: "A finite impulse response (FIR) filter has an impulse response of finite length and no feedback. It is always stable and can have exactly linear phase.",
    points: ["Output: y[n] = Σ_{k=0}^{M−1} h[k] x[n − k]. The system function has only zeros (apart from poles at the origin).", "Linear phase needs symmetric (h[n] = h[M − 1 − n]) or antisymmetric coefficients. Then every frequency is delayed by the same (M − 1)/2 samples.", "Window method: take the ideal low-pass impulse response hd[n] = sin(ωc(n − α)) / (π(n − α)) with α = (M − 1)/2 and multiply by a window w[n].", "Truncating abruptly (rectangular window) gives ripples near the cutoff (Gibbs phenomenon). Smoother windows reduce ripples but widen the transition band.", "Typical window trade-off: Rectangular: narrowest transition (4π/M) and about −21 dB stopband; Hanning (8π/M, about −44 dB); Hamming (8π/M, about −53 dB); Blackman (12π/M, about −74 dB).", "More coefficients (larger M) give a sharper transition at higher cost. FIR needs more computation than IIR for the same sharpness."],
    formulas: [["FIR output", "y[n] = Σ h[k] x[n − k]"], ["Linear phase", "h[n] = h[M − 1 − n]"], ["Delay", "(M − 1) / 2 samples"], ["Ideal LPF", "hd[n] = sin(ωc (n − α)) / (π (n − α))"], ["Windowed filter", "h[n] = hd[n] · w[n]"], ["Hamming window", "w[n] = 0.54 − 0.46 cos(2π n / (M − 1))"]],
    example: { title: "3-point moving-average filter, h = {1/3, 1/3, 1/3}", text: "y[n] = (x[n] + x[n − 1] + x[n − 2]) / 3\nThe coefficients are symmetric → linear phase, delay = 1 sample.\nIt smooths the signal: a low-pass FIR filter." },
    exam: "An FIR filter has a finite-duration impulse response and its output is y[n] = Σh[k]x[n − k]. It is always stable and can be designed to have exactly linear phase if its coefficients are symmetric. In the window method the ideal impulse response is truncated with a window function; the rectangular window gives the narrowest transition band but the largest ripples, while the Hamming and Blackman windows give lower ripple at the cost of a wider transition band.",
    mistakes: ["Saying FIR filters can be unstable. A non-recursive FIR filter is always stable.", "Using an even number of taps when the design needs a symmetric odd length.", "Expecting a rectangular window to give small stopband ripple. It does not."],
    uses: [["Audio equalisers and effects", "FIR filters keep the phase of the music unchanged."], ["Data communication", "Matched and pulse-shaping filters are FIR."], ["Biomedical signals", "ECG noise removal without distorting the wave shape."]], related: ["IIR filters", "LTI systems and convolution", "DTFT and DFT"], diagrams: ["firfilter", "lpfresp"] },
  { id: "iir", subject: DSP, keys: ["iir filter", "iir filters", "iir filter design", "butterworth filter", "chebyshev filter", "bilinear transform", "impulse invariance", "infinite impulse response", "direct form", "cascade form", "parallel form", "frequency warping", "analog filter design", "analog prototype"], title: "IIR filters, Butterworth and the bilinear transform",
    short: "An infinite impulse response (IIR) filter uses feedback, so it gives a sharp response with few coefficients. It is designed from an analog prototype such as Butterworth or Chebyshev.",
    points: ["Difference equation: y[n] = −Σ a_k y[n − k] + Σ b_k x[n − k]. H(z) has both poles and zeros.", "Stable only if all poles are inside the unit circle. IIR filters cannot have exactly linear phase.", "Butterworth: maximally flat magnitude |H(jΩ)|² = 1/(1 + (Ω/Ωc)^(2N)), −3 dB at Ωc, monotonic. Chebyshev I: equal ripple in the passband and monotonic in the stopband, with a sharper roll-off than Butterworth for the same order.", "Impulse invariance: h[n] = h_a(nT). It may cause aliasing and suits only band-limited (low-pass) filters.", "Bilinear transform: s = (2/T)(1 − z⁻¹)/(1 + z⁻¹). It maps the whole jΩ axis onto the unit circle (no aliasing), but the frequency scale is warped: Ω = (2/T) tan(ω/2). Critical frequencies must be pre-warped.", "Structures: direct form I, direct form II (fewest delays), cascade of second-order sections (best for sensitivity) and parallel form."],
    formulas: [["Butterworth", "|H(jΩ)|² = 1 / (1 + (Ω/Ωc)^(2N))"], ["Bilinear transform", "s = (2/T)(1 − z⁻¹) / (1 + z⁻¹)"], ["Frequency warping", "Ω = (2/T) tan(ω/2)"], ["Impulse invariance", "h[n] = T · h_a(nT)"], ["Order of Butterworth", "N ≥ log(√((10^(0.1αs) − 1)/(10^(0.1αp) − 1))) / log(Ωs/Ωp)"]],
    example: { title: "First-order IIR: y[n] = 0.8 y[n − 1] + 0.2 x[n]", text: "H(z) = 0.2 / (1 − 0.8 z⁻¹), pole at z = 0.8 (inside the unit circle: stable)\nDC gain: H(1) = 0.2 / (1 − 0.8) = 1\nIt is a simple low-pass (exponential smoothing) filter." },
    exam: "An IIR filter has an impulse response of infinite duration and is realised recursively. Digital IIR filters are designed by converting an analog prototype using the impulse invariance method or the bilinear transformation s = (2/T)(1 − z⁻¹)/(1 + z⁻¹). The bilinear transformation avoids aliasing but introduces frequency warping, Ω = (2/T)tan(ω/2). The Butterworth response is maximally flat in the passband.",
    mistakes: ["Forgetting to pre-warp the cutoff frequency before the bilinear transform.", "Using impulse invariance for a high-pass filter, where aliasing destroys the response.", "Treating an IIR filter as unconditionally stable."],
    uses: [["Audio tone controls", "A few coefficients give a sharp bass or treble cut."], ["Sensor smoothing", "Exponential smoothing on microcontrollers is a one-pole IIR."], ["Digital communications", "IIR filters keep the hardware small."]], related: ["FIR filters and window design", "Z-transform", "DTFT and DFT"], diagrams: ["iirfilter", "pzplot"] },
  { id: "adc", subject: DSP, keys: ["quantization", "quantisation", "quantization error", "quantization noise", "sqnr", "adc", "dac", "analog to digital converter", "digital to analog converter", "flash adc", "sar adc", "sigma delta", "resolution of adc", "bits of resolution", "quantiser"], title: "A/D conversion and quantisation",
    short: "An A/D converter samples a signal and then rounds each sample to one of 2^N levels (quantisation). The rounding error appears as quantisation noise.",
    points: ["The three steps are sampling, quantisation and encoding (to binary).", "Step size (resolution) Δ = (Vmax − Vmin) / 2^N for an N-bit converter.", "Quantisation error lies between −Δ/2 and +Δ/2, and its power is Δ²/12 (assuming a uniform error).", "SQNR for a full-scale sine wave is about 6.02N + 1.76 dB. Each extra bit improves it by about 6 dB.", "ADC types: flash (fastest, 2^N − 1 comparators), successive approximation SAR (medium speed, N clock cycles) and sigma-delta (high resolution, slower).", "A DAC converts the binary code back to a voltage, followed by a reconstruction filter."],
    formulas: [["Number of levels", "L = 2^N"], ["Step size", "Δ = (Vmax − Vmin) / 2^N"], ["Quantisation noise power", "σ² = Δ² / 12"], ["SQNR (sine)", "SQNR = 6.02 N + 1.76 dB"], ["Bit rate", "R = N · fs"]],
    example: { title: "12-bit ADC, range 0–3.3 V", text: "Levels = 2¹² = 4096\nΔ = 3.3 V / 4096 = 0.806 mV\nSQNR = 6.02 × 12 + 1.76 = 74 dB\nCD audio uses 16 bits: SQNR ≈ 98 dB." },
    exam: "Analog-to-digital conversion consists of sampling, quantisation and coding. The quantisation step size is Δ = (Vmax − Vmin)/2^N. The quantisation error is uniformly distributed between −Δ/2 and +Δ/2, giving noise power Δ²/12. For a full-scale sinusoid the signal-to-quantisation-noise ratio is 6.02N + 1.76 dB, so each additional bit improves SQNR by about 6 dB.",
    mistakes: ["Using 2^N − 1 intervals in one formula and 2^N in another without being consistent.", "Saying more bits reduce aliasing. Only the sampling rate and the anti-aliasing filter do that.", "Forgetting the 1.76 dB constant."],
    uses: [["Smartphone microphones and cameras", "Every sound and picture is quantised."], ["Microcontroller sensors", "A 10- or 12-bit ADC reads temperature and light."], ["Medical and test equipment", "High-resolution ADCs measure tiny signals."]], related: ["Sampling theorem and aliasing", "Discrete-time signals and systems", "Multirate signal processing"], diagrams: ["quant"] },
  { id: "multirate", subject: DSP, keys: ["multirate", "multirate signal processing", "decimation", "interpolation", "downsampling", "upsampling", "sampling rate conversion", "polyphase", "decimator", "interpolator"], title: "Multirate signal processing (decimation and interpolation)",
    short: "Multirate processing changes the sampling rate of a signal. Decimation lowers the rate by M, and interpolation raises it by L.",
    points: ["Decimation by M: low-pass filter first (cutoff π/M) to avoid aliasing, then keep every M-th sample. The new rate is fs/M.", "Interpolation by L: insert L − 1 zeros between samples (upsampling), then low-pass filter (cutoff π/L) with gain L. The new rate is L·fs.", "Rational rate change by L/M: interpolate by L first, then decimate by M (one filter can do both).", "Polyphase structures make the filters work at the lower rate and save computation.", "Used to match different sampling rates, for example 44.1 kHz audio to 48 kHz."],
    formulas: [["Decimation", "y[m] = x[m M],  fs' = fs / M"], ["Upsampling", "y[n] = x[n/L] if n is a multiple of L, else 0"], ["New rate", "fs' = (L/M) · fs"], ["Anti-alias cutoff", "ωc ≤ π / M"], ["Interpolation gain", "L"]],
    example: { title: "Convert 48 kHz audio to 44.1 kHz", text: "44100 / 48000 = 147 / 160\nInterpolate by L = 147, filter, then decimate by M = 160." },
    exam: "Decimation reduces the sampling rate by an integer factor M by passing the signal through a low-pass filter with cutoff π/M and keeping every M-th sample. Interpolation increases the rate by an integer factor L by inserting L − 1 zero samples between successive samples and filtering with a low-pass filter of gain L and cutoff π/L. A rational conversion factor L/M is achieved by cascading the two.",
    mistakes: ["Downsampling without the anti-aliasing filter.", "Forgetting the gain L of the interpolation filter.", "Doing the decimation before the interpolation, which loses information."],
    uses: [["Audio and video conversion", "Sound is converted between 44.1 kHz and 48 kHz."], ["Software-defined radio", "Wide-band samples are decimated to the wanted channel."], ["Efficient filtering", "Processing at lower rates saves power."]], related: ["Sampling theorem and aliasing", "FIR filters and window design", "A/D conversion and quantisation"], diagrams: ["multirate"] },
);
PACKS_ECE.push(
  { id: "cstypes", subject: CS, keys: ["open loop", "closed loop", "open loop control", "closed loop control", "feedback control system", "control system basics", "control system", "control systems", "servo mechanism", "regenerative feedback", "sensitivity of control system", "effects of feedback control"], title: "Open-loop and closed-loop control systems",
    short: "A control system makes an output (such as speed or temperature) follow a desired input. Open-loop systems do not measure the output. Closed-loop systems measure it and correct the error.",
    points: ["Open-loop: output does not affect the control action. Simple and cheap, but not accurate if conditions change (a toaster with a fixed timer).", "Closed-loop (feedback): the output is measured, compared with the reference and the error drives the controller (an air conditioner with a thermostat).", "Advantages of feedback: better accuracy, less sensitivity to parameter changes, rejection of disturbances, faster response.", "Disadvantages: more complex, higher cost, gain is reduced, and it can become unstable or oscillate.", "Negative feedback subtracts the output from the reference. Positive feedback adds it and tends to cause instability or latching.", "Sensitivity of a closed-loop system to changes in G is S = 1 / (1 + GH)."],
    formulas: [["Closed-loop transfer function", "C(s)/R(s) = G(s) / (1 + G(s)H(s))"], ["Error", "E(s) = R(s) − B(s),  B(s) = H(s) C(s)"], ["Sensitivity", "S = 1 / (1 + GH)"], ["Open-loop TF", "G(s)H(s)"], ["Characteristic equation", "1 + G(s)H(s) = 0"]],
    example: { title: "Open loop gain G = 100, unity feedback H = 1", text: "Closed-loop gain = 100 / (1 + 100) = 0.99\nIf G changes by 10% to 90: closed-loop gain = 90 / 91 = 0.989\nThe closed-loop gain hardly changes (very low sensitivity)." },
    exam: "A control system is an arrangement of components that controls the behaviour of another system. In an open-loop system the control action is independent of the output; in a closed-loop system the output is fed back and compared with the input so that the control action depends on the error. For negative feedback the closed-loop transfer function is C(s)/R(s) = G(s)/(1 + G(s)H(s)).",
    mistakes: ["Calling a system closed-loop without actually measuring the output.", "Using G/(1 − GH) for negative feedback. It is G/(1 + GH).", "Saying feedback always improves stability. It can also destabilise a system."],
    uses: [["Air conditioners and refrigerators", "A thermostat closes the loop on temperature."], ["Cruise control in cars", "The speed is measured and the throttle corrected."], ["Drones and robots", "Sensors and controllers hold position and balance."]], related: ["Transfer function and Laplace transform", "Block diagram reduction", "Steady-state error and system type"], diagrams: ["openloop", "closedloop"] },
  { id: "tf", subject: CS, keys: ["transfer function", "laplace transform", "laplace", "poles and zeros", "mathematical modelling", "mechanical system modelling", "electrical analogy", "force voltage analogy", "force current analogy", "mass spring damper", "final value theorem", "initial value theorem", "modeling of systems"], title: "Transfer function and Laplace transform",
    short: "The transfer function of a linear time-invariant system is the ratio of the Laplace transform of the output to that of the input, with all initial conditions zero.",
    points: ["G(s) = C(s) / R(s). Its roots in the denominator are the poles; roots of the numerator are the zeros. The characteristic equation is the denominator set to 0.", "Laplace pairs: unit step 1/s; unit ramp 1/s²; e^(−at) ↔ 1/(s + a); sin ωt ↔ ω/(s² + ω²); cos ωt ↔ s/(s² + ω²). Derivative: d/dt ↔ s (zero initial conditions).", "Mass–spring–damper: M ẍ + B ẋ + K x = f(t), so X(s)/F(s) = 1 / (M s² + B s + K).", "Analogies: force–voltage: mass ↔ inductance, damper ↔ resistance, spring ↔ 1/capacitance. Force–current: mass ↔ capacitance, damper ↔ 1/resistance, spring ↔ 1/inductance.", "Final value theorem: lim(t→∞) f(t) = lim(s→0) s F(s), valid only if the poles of sF(s) are in the left half-plane. Initial value theorem: f(0⁺) = lim(s→∞) s F(s)."],
    formulas: [["Transfer function", "G(s) = L{output} / L{input}  (zero initial conditions)"], ["RC low-pass", "Vo/Vi = 1 / (RC s + 1)"], ["Mass–spring–damper", "X(s)/F(s) = 1 / (M s² + B s + K)"], ["Final value", "f(∞) = lim s F(s) as s → 0"], ["Step response", "C(s) = G(s)/s"]],
    example: { title: "RC circuit with R = 1 kΩ and C = 1 µF", text: "G(s) = 1 / (RC s + 1) = 1 / (0.001 s + 1)\nPole at s = −1000 rad/s\nTime constant τ = RC = 1 ms\nStep response: vo(t) = 1 − e^(−t/τ) volts." },
    exam: "The transfer function of a linear time-invariant system is defined as the ratio of the Laplace transform of the output to the Laplace transform of the input, assuming zero initial conditions. The roots of the numerator are the zeros and the roots of the denominator are the poles. For a mass–spring–damper system, X(s)/F(s) = 1/(Ms² + Bs + K).",
    mistakes: ["Including initial conditions in the transfer function.", "Applying the final value theorem to an unstable or oscillating system.", "Mixing up the force–voltage and force–current analogies."],
    uses: [["Designing any controller", "All control design starts with the transfer function of the plant."], ["Electrical and mechanical systems", "Circuits and spring–mass systems share the same mathematics."], ["Simulation tools", "MATLAB and Simulink use transfer functions directly."]], related: ["Block diagram reduction", "Time response and specifications", "Stability and the Routh–Hurwitz criterion"], diagrams: [] },
  { id: "blockred", subject: CS, keys: ["block diagram", "block diagram reduction", "block diagram algebra", "reduction of block diagrams", "series blocks", "parallel blocks", "feedback loop reduction", "summing point", "take off point", "block diagram rules"], title: "Block diagram reduction",
    short: "A block diagram shows how signals flow between the parts of a system. Reduction rules combine many blocks into one transfer function.",
    points: ["Series (cascade) blocks multiply: G1 · G2.", "Parallel blocks add (or subtract with sign): G1 ± G2.", "Negative feedback loop: G / (1 + GH). Positive feedback loop: G / (1 − GH).", "Moving a summing point or take-off point past a block needs a compensating block (multiply or divide by that block) so the signals stay the same.", "Work from the inside loops outwards, and redraw after each step.", "For unity feedback (H = 1): C/R = G / (1 + G)."],
    formulas: [["Series", "G = G1 G2"], ["Parallel", "G = G1 + G2"], ["Negative feedback", "G / (1 + G H)"], ["Positive feedback", "G / (1 − G H)"], ["Unity feedback", "G / (1 + G)"]],
    example: { title: "G = 10/(s + 1) with feedback H = 0.5 (negative)", text: "C/R = G / (1 + GH) = [10/(s + 1)] / [1 + 5/(s + 1)]\n= 10 / (s + 1 + 5) = 10 / (s + 6)" },
    exam: "Block diagram reduction uses the following rules: blocks in series are multiplied, blocks in parallel are added algebraically, and a negative feedback loop is replaced by G/(1 + GH). To move a summing point or a take-off point across a block, a compensating block must be added so that the signal values remain unchanged. The diagram is reduced step by step until a single block remains.",
    mistakes: ["Forgetting the sign at the summing point.", "Moving a take-off point without the compensating block.", "Using 1 − GH for negative feedback."],
    uses: [["Understanding complex machines", "A robot or motor drive is drawn as blocks before it is analysed."], ["Simulink models", "Software tools use block diagrams directly."]], related: ["Signal flow graph and Mason’s gain formula", "Transfer function and Laplace transform", "Open-loop and closed-loop control systems"], diagrams: ["blockrules"] },
  { id: "sfg", subject: CS, keys: ["signal flow graph", "signal flow graphs", "masons gain formula", "mason's gain formula", "mason gain formula", "masons rule", "forward path", "non touching loops", "loop gain sfg"], title: "Signal flow graph and Mason’s gain formula",
    short: "A signal flow graph (SFG) draws a system as nodes joined by directed branches with gains. Mason’s gain formula finds the overall transfer function directly from the graph.",
    points: ["Node: a variable. Branch: a gain between two nodes. Source node has only outgoing branches; sink node only incoming.", "Forward path: a path from input to output that passes each node once. Loop: a closed path that touches each node once. Non-touching loops share no node.", "Mason’s formula: T = (Σ P_k Δ_k) / Δ.", "Δ = 1 − (sum of all loop gains) + (sum of products of gains of all pairs of non-touching loops) − (triples of non-touching loops) + …", "Δ_k is Δ with the loops that touch the k-th forward path removed.", "Every block diagram can be turned into an SFG and the other way round."],
    formulas: [["Mason’s formula", "T = Σ (P_k Δ_k) / Δ"], ["Determinant", "Δ = 1 − ΣL₁ + ΣL₂ − ΣL₃ + …"], ["Loop gain", "product of branch gains around a loop"]],
    example: { title: "One path R → x1 → x2 → C with gains G1, G2, G3 and loops −G2H1 and −G3H2", text: "P₁ = G1 G2 G3\nLoops: L₁ = −G2 H1,  L₂ = −G3 H2 (they touch: no non-touching pair)\nΔ = 1 − (−G2H1 − G3H2) = 1 + G2H1 + G3H2\nΔ₁ = 1 (no loop is free of the path)\nT = G1G2G3 / (1 + G2H1 + G3H2)" },
    exam: "Mason’s gain formula gives the overall gain of a signal flow graph as T = (ΣP_kΔ_k)/Δ, where P_k is the gain of the k-th forward path, Δ = 1 − (sum of loop gains) + (sum of products of gains of non-touching loops taken two at a time) − …, and Δ_k is the value of Δ after removing the loops touching the k-th forward path.",
    mistakes: ["Counting the same loop twice, or missing a loop.", "Treating touching loops as non-touching.", "Forgetting the signs of the loop gains for negative feedback."],
    uses: [["Analysing complicated feedback systems", "Faster than reducing a block diagram step by step."], ["Circuit theory", "SFGs are also used for electric networks."]], related: ["Block diagram reduction", "Transfer function and Laplace transform"], diagrams: ["mason"] },
  { id: "timeresp", subject: CS, keys: ["time response", "transient response", "first order system", "second order system", "damping ratio", "natural frequency", "peak overshoot", "rise time", "settling time", "peak time", "underdamped", "overdamped", "critically damped", "time domain specifications", "step response", "time constant"], title: "Time response and specifications (first and second order)",
    short: "The time response shows how the output of a system changes with time after an input is applied. The step response of a second-order system is described by ζ, ωn, overshoot, rise time and settling time.",
    points: ["First-order system: C/R = 1 / (τs + 1). Step response c(t) = 1 − e^(−t/τ). Time constant τ; settling time (2%) ts = 4τ; rise time (10–90%) tr = 2.2τ.", "Standard second-order system: C/R = ωn² / (s² + 2ζωn s + ωn²). ωn is the undamped natural frequency and ζ the damping ratio.", "Cases: ζ = 0 undamped (oscillates), 0 < ζ < 1 underdamped (overshoot), ζ = 1 critically damped, ζ > 1 overdamped (slow, no overshoot).", "Underdamped specifications: damped frequency ωd = ωn√(1 − ζ²), peak time tp = π/ωd, percent overshoot Mp = e^(−πζ/√(1 − ζ²)) × 100%, settling time ts ≈ 4/(ζωn) for 2% (3/(ζωn) for 5%).", "Rise time tr = (π − θ)/ωd, where θ = cos⁻¹ζ.", "Poles are at s = −ζωn ± jωd. A larger real part gives faster decay; ζ sets the overshoot."],
    formulas: [["First order", "c(t) = 1 − e^(−t/τ),  ts(2%) = 4τ"], ["Second order TF", "ωn² / (s² + 2ζωn s + ωn²)"], ["Damped frequency", "ωd = ωn √(1 − ζ²)"], ["Peak time", "tp = π / ωd"], ["Peak overshoot", "Mp = e^(−πζ/√(1 − ζ²)) × 100%"], ["Settling time (2%)", "ts = 4 / (ζ ωn)"], ["Rise time", "tr = (π − cos⁻¹ζ) / ωd"]],
    example: { title: "Second-order system with ωn = 5 rad/s and ζ = 0.5", text: "ωd = 5 × √(1 − 0.25) = 4.33 rad/s\ntp = π / 4.33 = 0.725 s\nMp = e^(−π × 0.5 / 0.866) = e^(−1.814) = 0.163 → 16.3%\nts (2%) = 4 / (0.5 × 5) = 1.6 s" },
    exam: "For a standard second-order system with transfer function ωn²/(s² + 2ζωn s + ωn²), the step response is underdamped for 0 < ζ < 1. The time-domain specifications are: peak time tp = π/ωd, percentage overshoot Mp = e^(−πζ/√(1−ζ²)) × 100%, settling time ts = 4/(ζωn) for the 2% criterion, and rise time tr = (π − θ)/ωd with θ = cos⁻¹ζ, where ωd = ωn√(1 − ζ²).",
    mistakes: ["Using ωn instead of ωd for the peak time.", "Mixing up the 2% and 5% settling-time formulas.", "Expecting overshoot for ζ ≥ 1."],
    uses: [["Designing motor and robot controllers", "Overshoot and settling time are the main targets."], ["Suspension in cars", "ζ is chosen for a comfortable ride without bouncing."], ["Instrument response", "Pointer and sensor settling is a second-order response."]], related: ["Steady-state error and system type", "Root locus", "Stability and the Routh–Hurwitz criterion"], diagrams: ["stepresp2"] },
  { id: "sserr", subject: CS, keys: ["steady state error", "steady state errors", "system type", "type of system", "position error constant", "velocity error constant", "acceleration error constant", "error constants", "kp kv ka", "static error constants"], title: "Steady-state error and system type",
    short: "Steady-state error is the difference between the desired and actual output after the transients die out. It depends on the system type (number of integrators) and the input.",
    points: ["For a unity-feedback system: ess = lim(s→0) s R(s) / (1 + G(s)).", "System type = number of poles of G(s) at s = 0 (number of pure integrators).", "Static error constants: Kp = lim G(s), Kv = lim s G(s), Ka = lim s² G(s) as s → 0.", "Step input: ess = 1/(1 + Kp). Ramp input: ess = 1/Kv. Parabolic input: ess = 1/Ka.", "Type 0: finite error for a step, infinite for ramp and parabola. Type 1: zero for a step, finite for a ramp, infinite for a parabola. Type 2: zero for step and ramp, finite for a parabola.", "A higher type improves accuracy but makes the system harder to keep stable."],
    formulas: [["Steady-state error", "ess = lim s R(s) / (1 + G(s)H(s))"], ["Position constant", "Kp = lim G(s)H(s)"], ["Velocity constant", "Kv = lim s G(s)H(s)"], ["Acceleration constant", "Ka = lim s² G(s)H(s)"], ["Step", "ess = 1 / (1 + Kp)"], ["Ramp", "ess = 1 / Kv"], ["Parabola", "ess = 1 / Ka"]],
    example: { title: "Unity feedback with G(s) = 10 / [s(s + 2)] and a unit ramp input", text: "Type 1 system (one pole at s = 0)\nKv = lim s·G(s) = 10 / 2 = 5\ness = 1 / Kv = 0.2\nFor a unit step input the error is 0 (Kp = ∞)." },
    exam: "The steady-state error of a unity-feedback system is ess = lim s→0 sR(s)/(1 + G(s)). The static error constants are Kp = lim G(s), Kv = lim sG(s) and Ka = lim s²G(s). For a step, ramp and parabolic input the steady-state errors are 1/(1 + Kp), 1/Kv and 1/Ka respectively. The type of a system is the number of integrators in the open-loop transfer function.",
    mistakes: ["Using the error formula for a non-unity feedback system without first reducing it.", "Counting the type from the closed-loop transfer function.", "Applying the formula to an unstable system."],
    uses: [["Position control of antennas and robots", "Type 1 or 2 makes the final position error zero."], ["Speed control of motors", "The error to a step reference sets the accuracy."]], related: ["Time response and specifications", "Stability and the Routh–Hurwitz criterion", "PID controllers"], diagrams: [] },
  { id: "routh", subject: CS, keys: ["routh hurwitz", "routh hurwitz criterion", "routh array", "routh criterion", "stability of control system", "stability", "stable system", "characteristic equation roots", "marginally stable", "bibo stability control", "auxiliary equation", "hurwitz"], title: "Stability and the Routh–Hurwitz criterion",
    short: "A linear system is stable if all roots of its characteristic equation lie in the left half of the s-plane. The Routh–Hurwitz criterion tests this without finding the roots.",
    points: ["Stable: all poles have negative real parts. Marginally stable: simple poles on the jω axis. Unstable: any pole in the right half-plane.", "Necessary condition: all coefficients of the characteristic polynomial must be present and have the same sign.", "Build the Routh array from the coefficients. The number of sign changes in the first column equals the number of roots in the right half-plane.", "Special case 1: a zero in the first column — replace it by a small positive ε and continue.", "Special case 2: a whole row of zeros — form the auxiliary polynomial from the row above, differentiate it and continue; the auxiliary roots (symmetric about the origin) may lie on the jω axis.", "Use the criterion to find the range of a gain K for stability."],
    steps: ["Write the characteristic equation in descending powers of s.", "Fill the first two rows with alternate coefficients.", "Each next entry = (determinant of two entries above) / (first entry of the row above), with a minus sign.", "Count the sign changes in the first column."],
    formulas: [["Routh entry", "b = (a₁·a₂ − a₀·a₃) / a₁  (pattern of the array)"], ["Right half-plane roots", "= number of sign changes in the first column"], ["Second order", "s² + a s + b: stable if a > 0 and b > 0"]],
    example: { title: "Range of K for stability: s³ + 2s² + 3s + K = 0", text: "s³ :  1     3\ns² :  2     K\ns¹ :  (6 − K)/2     0\ns⁰ :  K\nFor no sign change: 6 − K > 0 and K > 0\nStable for 0 < K < 6. At K = 6 the s¹ row is zero (marginal stability, sustained oscillation)." },
    exam: "A linear time-invariant system is stable if all the roots of its characteristic equation have negative real parts. The Routh–Hurwitz criterion states that the number of roots in the right half of the s-plane equals the number of sign changes in the first column of the Routh array. A necessary condition for stability is that all coefficients of the characteristic polynomial are present and positive.",
    mistakes: ["Skipping the necessary condition (missing or negative coefficients mean instability).", "Mixing up the sign pattern when computing the array entries.", "Forgetting the auxiliary equation when a whole row is zero."],
    uses: [["Choosing a safe controller gain", "Find the largest K before the loop oscillates."], ["Quick stability check without a computer", "Used in exams and design calculations."]], related: ["Root locus", "Bode plot (frequency response)", "Time response and specifications"], diagrams: ["splane"] },
  { id: "rlocus", subject: CS, keys: ["root locus", "root locus rules", "root locus technique", "breakaway point", "asymptotes root locus", "centroid", "angle of departure", "angle of arrival", "root locus plot", "locus of roots"], title: "Root locus",
    short: "The root locus is a plot of the closed-loop poles in the s-plane as the loop gain K changes from 0 to ∞. It shows how gain affects stability and the transient response.",
    points: ["The locus starts (K = 0) at the open-loop poles and ends (K → ∞) at the open-loop zeros or at infinity.", "Number of branches = number of open-loop poles (P) when P ≥ Z. The locus is symmetric about the real axis.", "Real-axis segments: a point lies on the locus if the number of open-loop poles plus zeros to its right is odd.", "Asymptotes: P − Z of them, with angles (2k + 1)·180° / (P − Z), meeting at the centroid σ = (Σ poles − Σ zeros) / (P − Z).", "Breakaway/break-in points: solve dK/ds = 0 (K from the characteristic equation).", "Crossing of the jω axis (limit of stability): use the Routh criterion or set s = jω.", "Constant-ζ lines help choose K for a given overshoot."],
    steps: ["Plot the open-loop poles (×) and zeros (○).", "Mark the real-axis segments.", "Find the asymptote angles and centroid.", "Find breakaway points and the jω-axis crossing.", "Sketch the branches and read off K = product of distances from the poles ÷ product of distances from the zeros."],
    formulas: [["Asymptote angles", "θ = (2k + 1) · 180° / (P − Z)"], ["Centroid", "σ = (Σ poles − Σ zeros) / (P − Z)"], ["Breakaway", "dK/ds = 0"], ["Magnitude condition", "|G(s)H(s)| = 1  → gives K"], ["Angle condition", "∠G(s)H(s) = ±(2k + 1) 180°"]],
    example: { title: "G(s)H(s) = K / [s(s + 2)]", text: "Poles at 0 and −2, no zeros: P − Z = 2\nReal axis: the segment from −2 to 0 is on the locus\nAsymptotes: ±90°, centroid σ = (0 − 2)/2 = −1\nK = −s(s + 2): dK/ds = −(2s + 2) = 0 → s = −1 (breakaway point, K = 1)\nFor K > 1 the poles are complex: −1 ± j√(K − 1)." },
    exam: "The root locus is the locus of the roots of the characteristic equation 1 + KG(s)H(s) = 0 as K varies from 0 to ∞. It starts at the open-loop poles and ends at the open-loop zeros. The number of asymptotes is P − Z, their angles are (2k + 1)180°/(P − Z), and the centroid is (Σ poles − Σ zeros)/(P − Z). Breakaway points are found from dK/ds = 0.",
    mistakes: ["Forgetting that the locus lies on the real axis to the left of an odd number of poles and zeros.", "Using (2k)·180° for the asymptote angles. It is (2k + 1)·180°.", "Treating a breakaway point that is not on the locus as a valid one."],
    uses: [["Tuning a motor or servo gain", "Read how the poles move as the gain is raised."], ["Checking the stability limit", "The point where the locus crosses the jω axis gives the maximum gain."]], related: ["Stability and the Routh–Hurwitz criterion", "Time response and specifications", "Bode plot (frequency response)"], diagrams: ["rootlocus"] },
  { id: "bode", subject: CS, keys: ["bode plot", "bode plots", "frequency response analysis", "gain margin", "phase margin", "gain crossover", "phase crossover", "corner frequency", "break frequency", "magnitude plot", "phase plot", "frequency domain specifications", "resonant peak", "bandwidth control"], title: "Bode plot (frequency response)",
    short: "A Bode plot shows the magnitude (in dB) and phase of G(jω) against log frequency. From it we read the gain margin and phase margin that tell how stable the closed loop is.",
    points: ["Magnitude: 20 log₁₀|G(jω)| dB. Each pole adds a slope of −20 dB/decade after its corner frequency; each zero adds +20 dB/decade. A pole at the origin starts the plot at −20 dB/decade.", "Phase of a simple pole: 0° well below the corner, −45° at the corner and −90° well above it. A zero gives the opposite sign.", "Gain crossover frequency ωgc: where |G| = 1 (0 dB). Phase crossover frequency ωpc: where the phase is −180°.", "Phase margin PM = 180° + ∠G(jωgc). Gain margin GM = 1 / |G(jωpc)| (in dB: −20 log|G(jωpc)|).", "The closed loop is stable if both PM and GM are positive. A good design has PM of about 45° to 60° and GM above 6 dB.", "For a first-order system 1/(1 + s/ωc): flat at 0 dB below ωc, then −20 dB/decade; the true gain at ωc is −3 dB."],
    formulas: [["Magnitude in dB", "20 log₁₀ |G(jω)|"], ["Phase margin", "PM = 180° + ∠G(jω_gc)"], ["Gain margin", "GM(dB) = −20 log₁₀ |G(jω_pc)|"], ["Slope per pole", "−20 dB/decade (−6 dB/octave)"], ["Corner frequency", "ωc = 1/τ  for the factor 1/(1 + τs)"]],
    example: { title: "G(s) = 1 / (1 + s/10)", text: "Corner frequency ωc = 10 rad/s.\nBelow 10 rad/s: |G| ≈ 0 dB. Above: falls at −20 dB/decade.\nAt ω = 10: |G| = 1/√2 = −3 dB and the phase = −45°.\nAt ω = 100: |G| ≈ −20 dB." },
    exam: "A Bode plot consists of a magnitude plot in decibels and a phase plot against the logarithm of frequency. Each simple pole contributes −20 dB/decade after its corner frequency and each zero +20 dB/decade. The phase margin is PM = 180° + ∠G(jωgc) at the gain crossover frequency and the gain margin is the reciprocal of |G(jωpc)| at the phase crossover frequency. A system is stable if both margins are positive.",
    mistakes: ["Using 10 log instead of 20 log for magnitude.", "Forgetting that the straight-line plot is an approximation (the true value is 3 dB lower at the corner).", "Reading the margin at the wrong crossover frequency."],
    uses: [["Audio and amplifier design", "The −3 dB points set the bandwidth."], ["Designing stable controllers", "Phase margin tells how safe the loop is from oscillating."], ["Testing real systems", "Frequency response is measured with a signal generator and analyser."]], related: ["Nyquist plot and stability", "Root locus", "Frequency response of amplifiers"], diagrams: ["bodemag"] },
  { id: "nyq", subject: CS, keys: ["nyquist plot", "nyquist criterion", "nyquist stability criterion", "polar plot", "encirclement", "nyquist stability"], title: "Nyquist plot and stability criterion",
    short: "The Nyquist criterion decides the stability of the closed loop from the polar plot of the open-loop transfer function G(jω)H(jω) and its encirclements of the point −1 + j0.",
    points: ["Plot G(jω)H(jω) for ω from −∞ to +∞ (the plot for negative ω is the mirror image about the real axis).", "Let P = number of open-loop poles in the right half-plane, N = number of clockwise encirclements of the point −1 + j0.", "Number of closed-loop poles in the right half-plane: Z = N + P. The closed loop is stable only if Z = 0.", "If the open loop is stable (P = 0), the closed loop is stable when the plot does not encircle −1.", "If G(s)H(s) has poles on the jω axis (such as an integrator), the contour is indented around them.", "Gain margin and phase margin can be read from the Nyquist plot: how far the curve is from −1 along the negative real axis and along the unit circle."],
    formulas: [["Nyquist criterion", "Z = N + P  (N counted clockwise)"], ["Stability condition", "Z = 0  →  N = −P"], ["Stable open loop", "P = 0 → no encirclement of −1"]],
    example: { title: "Open loop with no right-half-plane poles (P = 0) and a plot that does not enclose −1", text: "N = 0, so Z = N + P = 0.\nThe closed-loop system is stable.\nIf the curve encircled −1 clockwise once: Z = 1 → one unstable closed-loop pole." },
    exam: "The Nyquist stability criterion states that the closed-loop system is stable if the Nyquist plot of the open-loop transfer function G(s)H(s) encircles the point −1 + j0 in the counter-clockwise direction as many times as the number of right-half-plane open-loop poles. In terms of the formula, Z = N + P, where N is the number of clockwise encirclements, and the closed loop is stable when Z = 0.",
    mistakes: ["Counting encirclements of the origin instead of the point −1.", "Mixing up the direction (clockwise counts as positive for N).", "Forgetting the mirror image for negative frequencies."],
    uses: [["Systems with delay or high-order dynamics", "Where root-locus sketches are hard, Nyquist still works."], ["Checking robustness", "The distance of the curve from −1 shows how safe the loop is."]], related: ["Bode plot (frequency response)", "Stability and the Routh–Hurwitz criterion", "Root locus"], diagrams: ["nyquist"] },
  { id: "pid", subject: CS, keys: ["pid controller", "pid controllers", "pid", "proportional controller", "integral controller", "derivative controller", "ziegler nichols", "pid tuning", "lead compensator", "lag compensator", "compensator", "controller design", "p i d control"], title: "PID controllers and compensators",
    short: "A PID controller combines proportional, integral and derivative action on the error. It is the most widely used controller in industry.",
    points: ["Proportional (P): output ∝ error. Reduces rise time but leaves a steady-state error.", "Integral (I): output ∝ the integral of the error. Removes the steady-state error but can increase overshoot and make the system oscillate.", "Derivative (D): output ∝ the rate of change of the error. Adds damping and reduces overshoot but amplifies noise.", "Ideal PID: Gc(s) = Kp (1 + 1/(Ti s) + Td s) = Kp + Ki/s + Kd s.", "Ziegler–Nichols tuning (ultimate-gain method): raise Kp until sustained oscillation (Ku, period Pu). Then PID: Kp = 0.6 Ku, Ti = 0.5 Pu, Td = 0.125 Pu. Step-response (reaction-curve) method with delay L and time constant T: PID: Kp = 1.2 T/L, Ti = 2L, Td = 0.5L (for a plant of unit steady-state gain; otherwise divide Kp by the plant gain).", "Lead compensator adds phase (improves speed and stability). Lag compensator improves steady-state accuracy without changing the transient much."],
    formulas: [["PID", "u(t) = Kp e + Ki ∫ e dt + Kd de/dt"], ["Transfer function", "Gc(s) = Kp (1 + 1/(Ti s) + Td s)"], ["Ziegler–Nichols (ultimate)", "Kp = 0.6 Ku,  Ti = 0.5 Pu,  Td = 0.125 Pu"], ["Ziegler–Nichols (reaction)", "Kp = 1.2 T/L,  Ti = 2L,  Td = 0.5L"], ["Lead network", "(1 + aTs) / (1 + Ts), a > 1"]],
    example: { title: "Ziegler–Nichols: Ku = 10 and Pu = 4 s", text: "Kp = 0.6 × 10 = 6\nTi = 0.5 × 4 = 2 s\nTd = 0.125 × 4 = 0.5 s\nKi = Kp/Ti = 3,  Kd = Kp·Td = 3" },
    exam: "A PID controller produces a control signal u(t) = Kp e(t) + Ki ∫e dt + Kd de/dt. Proportional action improves the speed of response, integral action removes the steady-state error and derivative action improves damping. The Ziegler–Nichols ultimate-gain method gives the settings Kp = 0.6Ku, Ti = 0.5Pu and Td = 0.125Pu for a PID controller.",
    mistakes: ["Expecting a P controller alone to remove the steady-state error of a type-0 plant.", "Using too much derivative gain on a noisy sensor.", "Using Ziegler–Nichols values as final. They are only a starting point."],
    uses: [["Temperature controllers and ovens", "PID keeps the temperature steady."], ["Drones, robots and cars", "Balance, speed and steering use PID loops."], ["Industrial process control", "Pressure, flow and level are controlled by PID."]], related: ["Steady-state error and system type", "Time response and specifications", "State-space analysis"], diagrams: ["pidblock"] },
  { id: "statesp", subject: CS, keys: ["state space", "state variable", "state variables", "state equations", "state model", "controllability", "observability", "state feedback", "state transition matrix", "modern control", "state space analysis", "eigenvalues of a"], title: "State-space analysis",
    short: "State-space models describe a system with first-order differential equations in matrix form. They work for multi-input, multi-output and time-varying systems, and also give controllability and observability tests.",
    points: ["Standard form: ẋ = A x + B u and y = C x + D u. x is the state vector, u the input and y the output.", "Transfer function from the model: G(s) = C (sI − A)⁻¹ B + D. The poles are the eigenvalues of A (roots of |sI − A| = 0).", "Controllability: the system can be driven from any state to any other if the controllability matrix [B  AB  …  A^(n−1)B] has rank n.", "Observability: the states can be found from the output if the observability matrix [C; CA; …; CA^(n−1)] has rank n.", "State feedback u = −Kx can place the closed-loop poles anywhere (pole placement) if the system is controllable.", "State transition matrix: x(t) = e^(At) x(0) + ∫ e^(A(t−τ)) B u(τ) dτ."],
    formulas: [["State model", "ẋ = Ax + Bu,  y = Cx + Du"], ["Transfer function", "G(s) = C (sI − A)⁻¹ B + D"], ["Characteristic equation", "|sI − A| = 0"], ["Controllability matrix", "Qc = [B  AB  …  A^(n−1)B]"], ["Observability matrix", "Qo = [C; CA; …; CA^(n−1)]"], ["State feedback", "u = −K x → A − BK"]],
    example: { title: "ẍ + 3ẋ + 2x = u with x₁ = x and x₂ = ẋ", text: "ẋ₁ = x₂,  ẋ₂ = −2x₁ − 3x₂ + u\nA = [[0, 1], [−2, −3]],  B = [0; 1],  C = [1  0]\n|sI − A| = s² + 3s + 2 → eigenvalues −1 and −2 (stable)\nG(s) = 1 / (s² + 3s + 2)" },
    exam: "The state-space model of a linear system is ẋ = Ax + Bu, y = Cx + Du. The transfer function is G(s) = C(sI − A)⁻¹B + D and the poles of the system are the eigenvalues of A. The system is completely controllable if the rank of [B AB … A^(n−1)B] is n and completely observable if the rank of [C; CA; …; CA^(n−1)] is n.",
    mistakes: ["Forgetting that the choice of state variables is not unique (but the eigenvalues are).", "Confusing controllability (inputs reach every state) with observability (outputs show every state).", "Mixing up the order of the matrices in the controllability matrix."],
    uses: [["Aircraft, rockets and robots", "Multi-variable control uses state-space models."], ["Modern optimal control (LQR, Kalman filter)", "Built on state-space models."], ["Computer simulation", "Simulators solve ẋ = Ax + Bu step by step."]], related: ["Transfer function and Laplace transform", "PID controllers and compensators", "Stability and the Routh–Hurwitz criterion"], diagrams: ["statespace"] },
  { id: "servo", subject: CS, keys: ["servo motor", "dc servo motor", "ac servo motor", "synchro", "tachogenerator", "tacho generator", "error detector", "potentiometer error detector", "armature controlled dc motor", "field controlled dc motor", "control system components", "stepper motor control"], title: "Control system components (servo motors, synchros, tachogenerators)",
    short: "Typical control systems use error detectors (potentiometers, synchros), actuators (servo motors) and sensors (tachogenerators) to build a position or speed control loop.",
    points: ["Potentiometer error detector: two potentiometers (reference and feedback) give a voltage proportional to the position error.", "Synchro: a transmitter–control transformer pair measures the angular misalignment between two shafts and gives a voltage proportional to the error.", "Tachogenerator: its output voltage is proportional to the shaft speed, used for speed feedback and damping.", "Armature-controlled DC servo motor: the field current is constant and the armature voltage controls the speed. Neglecting the armature inductance, θ(s)/Va(s) = K / [s(τ s + 1)].", "Armature-controlled motors have good linearity and fast response and are preferred for servo systems. Field-controlled motors are used for small power applications.", "AC servo motors are two-phase motors with a high-resistance rotor, giving a speed–torque curve that falls with speed (a damping effect)."],
    formulas: [["Armature-controlled DC motor", "θ(s)/Va(s) = Km / {s [Ra(Js + B) + Km Kb]}"], ["Simplified form", "θ(s)/Va(s) = K / [s(τ s + 1)]"], ["Constants", "K = Km / (Ra B + Km Kb),  τ = Ra J / (Ra B + Km Kb)"], ["Back emf", "eb = Kb · dθ/dt"], ["Torque", "T = Km · ia"]],
    example: { title: "Why add a tachogenerator to a position servo?", text: "The tachogenerator feeds back the speed (a derivative of position).\nThis adds damping, which reduces the overshoot of the position response." },
    exam: "In an armature-controlled DC servo motor the field current is constant and the armature voltage is the control input. Neglecting the armature inductance the transfer function is θ(s)/Va(s) = K/[s(τs + 1)], where K = Km/(RaB + KmKb) and τ = RaJ/(RaB + KmKb). A synchro pair acts as an error detector for angular position, and a tachogenerator gives a voltage proportional to speed.",
    mistakes: ["Forgetting the back emf term Kb in the transfer function.", "Mixing up armature-controlled and field-controlled motors.", "Treating a tachogenerator as a position sensor. It measures speed."],
    uses: [["CNC machines and robot arms", "Servo motors position the tool accurately."], ["Antenna and radar tracking", "Synchros or encoders give the position error."], ["Printers and camera focus", "Small servo loops keep the head on target."]], related: ["PID controllers and compensators", "Time response and specifications", "Transfer function and Laplace transform"], diagrams: ["closedloop"] },
);
PACKS_ECE.push(
  { id: "probbasic", subject: PRB, keys: ["probability", "probability basics", "axioms of probability", "sample space", "conditional probability", "independent events", "mutually exclusive events", "permutations and combinations", "addition theorem of probability", "multiplication theorem", "probability theory", "events and sample space", "venn diagram"], title: "Probability basics: axioms, conditional probability and independence",
    short: "Probability measures how likely an event is, on a scale from 0 (impossible) to 1 (certain). It is built from three axioms on a sample space of all possible outcomes.",
    points: ["Axioms: P(A) ≥ 0, P(S) = 1, and for mutually exclusive events P(A ∪ B) = P(A) + P(B).", "Complement: P(A′) = 1 − P(A). Addition rule: P(A ∪ B) = P(A) + P(B) − P(A ∩ B).", "Equally likely outcomes: P(A) = n(A) / n(S).", "Conditional probability: P(A | B) = P(A ∩ B) / P(B), with P(B) > 0. Multiplication rule: P(A ∩ B) = P(A | B) P(B).", "Independent events: P(A ∩ B) = P(A) P(B), which means P(A | B) = P(A).", "Mutually exclusive events cannot happen together. Two events with non-zero probability cannot be both mutually exclusive and independent.", "Counting: permutations nPr = n!/(n − r)! (order matters) and combinations nCr = n!/(r!(n − r)!) (order does not matter)."],
    formulas: [["Complement", "P(A′) = 1 − P(A)"], ["Addition", "P(A ∪ B) = P(A) + P(B) − P(A ∩ B)"], ["Conditional", "P(A | B) = P(A ∩ B) / P(B)"], ["Independence", "P(A ∩ B) = P(A) P(B)"], ["Permutations", "nPr = n! / (n − r)!"], ["Combinations", "nCr = n! / (r! (n − r)!)"]],
    example: { title: "Two fair dice are rolled. Find P(sum = 7) and P(sum = 7 | first die is 3).", text: "Sample space: 36 equally likely outcomes.\nSum = 7: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1) → 6 outcomes\nP(sum = 7) = 6/36 = 1/6\nGiven the first die is 3, only (3,4) gives 7:\nP(sum = 7 | first = 3) = 1/6  (the two events are independent)" },
    exam: "Probability is a measure between 0 and 1 satisfying three axioms: P(A) ≥ 0, P(S) = 1 and P(A ∪ B) = P(A) + P(B) for mutually exclusive events. The conditional probability of A given B is P(A|B) = P(A ∩ B)/P(B). Two events are independent if P(A ∩ B) = P(A)P(B). The addition rule is P(A ∪ B) = P(A) + P(B) − P(A ∩ B).",
    mistakes: ["Using P(A) + P(B) for events that are not mutually exclusive.", "Saying mutually exclusive events are independent. They are not.", "Using permutations when the order does not matter."],
    uses: [["Communication and error rates", "Bit-error probability is a probability model."], ["Reliability engineering", "The chance a machine works for a given time."], ["Machine learning", "Classification is built on conditional probability."]], related: ["Total probability and Bayes’ theorem", "Random variables and distributions (PMF, PDF, CDF)", "Expectation, variance and moments"], diagrams: ["venn"] },
  { id: "bayes", subject: PRB, keys: ["bayes theorem", "bayes", "bayes rule", "total probability", "total probability theorem", "prior probability", "posterior probability", "likelihood", "probability tree", "tree diagram probability", "false positive"], title: "Total probability and Bayes’ theorem",
    short: "The theorem of total probability finds the chance of an event by adding over all the ways it can happen. Bayes’ theorem reverses a conditional probability: it finds the probability of a cause given the observed effect.",
    points: ["Let B₁, …, Bₙ be mutually exclusive and exhaustive events (a partition of S).", "Total probability: P(A) = Σ P(A | Bᵢ) P(Bᵢ).", "Bayes’ theorem: P(Bⱼ | A) = P(A | Bⱼ) P(Bⱼ) / Σ P(A | Bᵢ) P(Bᵢ).", "P(Bᵢ) are the prior probabilities, P(A | Bᵢ) the likelihoods and P(Bⱼ | A) the posterior probabilities.", "A probability tree helps: multiply along a branch, add across branches.", "Even with an accurate test, a rare condition gives many false positives (the base-rate effect)."],
    formulas: [["Total probability", "P(A) = Σ P(A | Bᵢ) P(Bᵢ)"], ["Bayes’ theorem", "P(Bⱼ | A) = P(A | Bⱼ) P(Bⱼ) / P(A)"], ["Two events", "P(B | A) = P(A | B) P(B) / [P(A | B) P(B) + P(A | B′) P(B′)]"]],
    example: { title: "A disease has 1% prevalence. A test is positive for 95% of sick people and 5% of healthy people.", text: "P(D) = 0.01,  P(+ | D) = 0.95,  P(+ | D′) = 0.05\nP(+) = 0.95 × 0.01 + 0.05 × 0.99 = 0.0095 + 0.0495 = 0.059\nP(D | +) = 0.0095 / 0.059 = 0.161 → about 16%\nMost positive results are false positives because the disease is rare." },
    exam: "If B₁, B₂, …, Bₙ form a partition of the sample space, the theorem of total probability states P(A) = ΣP(A|Bᵢ)P(Bᵢ). Bayes’ theorem states that P(Bⱼ|A) = P(A|Bⱼ)P(Bⱼ) / ΣP(A|Bᵢ)P(Bᵢ). It is used to update the probability of a cause after an effect is observed.",
    mistakes: ["Confusing P(A|B) with P(B|A).", "Forgetting the denominator P(A) in Bayes’ theorem.", "Using a partition whose events overlap or do not cover the whole sample space."],
    uses: [["Spam filters and medical tests", "Naive Bayes classifiers decide using these formulas."], ["Digital communication", "A receiver decides which symbol was sent from the received signal."], ["Fault diagnosis", "Which component failed, given the symptom."]], related: ["Probability basics: axioms, conditional probability and independence", "Random variables and distributions (PMF, PDF, CDF)"], diagrams: ["bayestree"] },
  { id: "rv", subject: PRB, keys: ["random variable", "random variables", "pmf", "pdf", "cdf", "probability mass function", "probability density function", "cumulative distribution function", "distribution function", "discrete random variable", "continuous random variable", "density function"], title: "Random variables and distributions (PMF, PDF, CDF)",
    short: "A random variable X assigns a number to each outcome of an experiment. Its behaviour is described by the PMF (discrete) or PDF (continuous) and by the CDF.",
    points: ["Discrete random variable: takes countable values. PMF p(x) = P(X = x), with p(x) ≥ 0 and Σ p(x) = 1.", "Continuous random variable: takes any value in an interval. PDF f(x) ≥ 0 with ∫ f(x) dx = 1. P(a < X < b) = ∫ₐᵇ f(x) dx, and P(X = a) = 0 for any single value.", "CDF: F(x) = P(X ≤ x). It is non-decreasing, right-continuous, F(−∞) = 0 and F(+∞) = 1.", "For a continuous variable f(x) = dF(x)/dx. For any type, P(a < X ≤ b) = F(b) − F(a).", "A PDF can be greater than 1 at some points (it is a density), but its total area must be 1."],
    formulas: [["PMF", "p(x) = P(X = x),  Σ p(x) = 1"], ["PDF", "f(x) ≥ 0,  ∫ f(x) dx = 1"], ["CDF", "F(x) = P(X ≤ x) = ∫ f(t) dt  (−∞ to x)"], ["Link", "f(x) = dF/dx"], ["Interval", "P(a < X ≤ b) = F(b) − F(a)"]],
    example: { title: "Continuous variable with f(x) = 2x for 0 ≤ x ≤ 1 (zero elsewhere)", text: "Check: ∫₀¹ 2x dx = 1 ✓\nF(x) = x² for 0 ≤ x ≤ 1\nP(X < 0.5) = F(0.5) = 0.25\nP(0.5 < X < 1) = 1 − 0.25 = 0.75" },
    exam: "A random variable is a function that assigns a real number to every outcome of a random experiment. For a discrete random variable the probability mass function p(x) = P(X = x) satisfies Σp(x) = 1. For a continuous random variable the probability density function f(x) satisfies ∫f(x)dx = 1 and P(a < X < b) = ∫f(x)dx. The cumulative distribution function F(x) = P(X ≤ x) is non-decreasing from 0 to 1, and f(x) = dF/dx.",
    mistakes: ["Saying the PDF value is a probability. Only the area under it is.", "Forgetting that P(X = a) = 0 for a continuous variable.", "Using a PDF that does not integrate to 1."],
    uses: [["Modelling noise and measurements", "Sensor error is modelled as a random variable."], ["Communication systems", "The received voltage with noise is a continuous random variable."], ["Quality control", "Component values vary with a PDF."]], related: ["Expectation, variance and moments", "Discrete distributions (Binomial, Poisson)", "Continuous distributions (Uniform, Exponential)"], diagrams: ["pdfcdf"] },
  { id: "moments", subject: PRB, keys: ["expectation", "expected value", "mean of random variable", "variance", "standard deviation", "moments", "moment generating function", "mgf", "chebyshev inequality", "chebyshev", "central moments", "characteristic function", "skewness", "kurtosis", "second moment"], title: "Expectation, variance and moments",
    short: "The expected value is the average value of a random variable, and the variance measures how spread out it is. Moments describe the shape of the distribution in more detail.",
    points: ["Mean: E[X] = Σ x p(x) (discrete) or ∫ x f(x) dx (continuous). For a function: E[g(X)] = Σ g(x) p(x) or ∫ g(x) f(x) dx.", "Linearity: E[aX + b] = aE[X] + b, and E[X + Y] = E[X] + E[Y] always (independent or not).", "Variance: σ² = E[(X − μ)²] = E[X²] − (E[X])². Var(aX + b) = a² Var(X). Standard deviation σ = √Var.", "nth moment: E[Xⁿ]. nth central moment: E[(X − μ)ⁿ]. Skewness uses the 3rd central moment and kurtosis the 4th.", "MGF: M(t) = E[e^(tX)]. The nth moment is the nth derivative at 0: E[Xⁿ] = M⁽ⁿ⁾(0).", "Chebyshev’s inequality: P(|X − μ| ≥ kσ) ≤ 1/k² for any distribution with finite variance."],
    formulas: [["Mean", "E[X] = Σ x p(x)  or  ∫ x f(x) dx"], ["Variance", "Var(X) = E[X²] − (E[X])²"], ["Linear change", "E[aX + b] = aE[X] + b,  Var(aX + b) = a² Var(X)"], ["MGF", "M(t) = E[e^(tX)],  E[Xⁿ] = M⁽ⁿ⁾(0)"], ["Chebyshev", "P(|X − μ| ≥ kσ) ≤ 1/k²"]],
    example: { title: "Fair six-sided die", text: "E[X] = (1 + 2 + 3 + 4 + 5 + 6) / 6 = 3.5\nE[X²] = (1 + 4 + 9 + 16 + 25 + 36) / 6 = 91/6 = 15.17\nVar(X) = 91/6 − 3.5² = 35/12 ≈ 2.92\nσ ≈ 1.71" },
    exam: "The expected value of a random variable X is E[X] = Σxp(x) for the discrete case and ∫xf(x)dx for the continuous case. The variance is Var(X) = E[X²] − (E[X])². For constants a and b, E[aX + b] = aE[X] + b and Var(aX + b) = a²Var(X). The moment generating function is M(t) = E[e^(tX)] and E[Xⁿ] = M⁽ⁿ⁾(0). Chebyshev’s inequality states P(|X − μ| ≥ kσ) ≤ 1/k².",
    mistakes: ["Writing Var(aX + b) = a Var(X) or adding b.", "Forgetting to subtract the square of the mean in E[X²] − (E[X])².", "Applying E[XY] = E[X]E[Y] to dependent variables."],
    uses: [["Signal power", "The mean square value E[X²] is the power of a signal."], ["Risk and error analysis", "Variance measures how uncertain a measurement is."], ["Statistics and machine learning", "Mean and variance summarise a dataset."]], related: ["Random variables and distributions (PMF, PDF, CDF)", "Gaussian (normal) distribution", "Law of large numbers and the central limit theorem"], diagrams: [] },
  { id: "discdist", subject: PRB, keys: ["binomial distribution", "poisson distribution", "bernoulli distribution", "geometric distribution", "discrete distributions", "binomial", "poisson", "bernoulli trial", "negative binomial", "hypergeometric", "poisson approximation"], title: "Discrete distributions (Bernoulli, Binomial, Poisson, Geometric)",
    short: "Standard discrete distributions model counts: the number of successes in trials (binomial), the number of rare events in an interval (Poisson) and the trial of the first success (geometric).",
    points: ["Bernoulli(p): one trial, success with probability p. Mean p, variance p(1 − p).", "Binomial(n, p): number of successes in n independent trials. P(X = k) = C(n,k) pᵏ (1 − p)ⁿ⁻ᵏ. Mean np, variance np(1 − p).", "Poisson(λ): number of events in a fixed interval when events occur independently at an average rate λ. P(X = k) = e^(−λ) λᵏ / k!. Mean = variance = λ.", "Poisson approximates the binomial when n is large and p is small, with λ = np.", "Geometric(p): number of trials until the first success. P(X = k) = (1 − p)ᵏ⁻¹ p. Mean 1/p, variance (1 − p)/p².", "Sum of independent Poisson variables is Poisson with the rates added."],
    formulas: [["Binomial", "P(X = k) = C(n,k) pᵏ q^(n−k),  E = np,  Var = npq"], ["Poisson", "P(X = k) = e^(−λ) λᵏ / k!,  E = Var = λ"], ["Geometric", "P(X = k) = q^(k−1) p,  E = 1/p,  Var = q/p²"], ["Bernoulli", "E = p,  Var = pq"], ["Poisson approximation", "λ = n p  (n large, p small)"]],
    example: { title: "A coin is tossed 6 times. Find P(exactly 3 heads). Calls arrive at 2 per minute: find P(no calls in a minute).", text: "Binomial n = 6, p = 0.5: P(3) = C(6,3)(0.5)⁶ = 20/64 = 0.3125\nPoisson λ = 2: P(0) = e^(−2) = 0.1353" },
    exam: "In the binomial distribution with parameters n and p, the probability of k successes is C(n,k)pᵏ(1 − p)ⁿ⁻ᵏ, with mean np and variance np(1 − p). In the Poisson distribution with parameter λ, the probability of k events is e^(−λ)λᵏ/k! with mean and variance both equal to λ. The Poisson distribution is a limiting case of the binomial distribution when n → ∞, p → 0 and np = λ.",
    mistakes: ["Using the binomial when the trials are not independent.", "Forgetting the C(n,k) factor.", "Saying the Poisson variance differs from its mean."],
    uses: [["Call centres and network packets", "Arrivals per minute follow a Poisson model."], ["Digital communication errors", "Number of bit errors in a block is binomial."], ["Quality inspection", "Number of defective items in a batch."]], related: ["Continuous distributions (Uniform, Exponential, Rayleigh)", "Random variables and distributions (PMF, PDF, CDF)", "Expectation, variance and moments"], diagrams: ["binomial"] },
  { id: "contdist", subject: PRB, keys: ["uniform distribution", "exponential distribution", "rayleigh distribution", "continuous distributions", "memoryless property", "continuous uniform", "exponential random variable", "rayleigh", "gamma distribution", "rician"], title: "Continuous distributions (Uniform, Exponential, Rayleigh)",
    short: "Common continuous distributions: the uniform distribution (all values in an interval are equally likely), the exponential (waiting times) and the Rayleigh (the envelope of noise in communication).",
    points: ["Uniform(a, b): f(x) = 1/(b − a) for a ≤ x ≤ b. Mean (a + b)/2, variance (b − a)²/12. Used for quantisation error and random phase.", "Exponential(λ): f(x) = λe^(−λx) for x ≥ 0. CDF F(x) = 1 − e^(−λx). Mean 1/λ, variance 1/λ². It has the memoryless property: P(X > s + t | X > s) = P(X > t).", "Exponential describes the time between events of a Poisson process (λ = the rate).", "Rayleigh: f(x) = (x/σ²) e^(−x²/(2σ²)) for x ≥ 0. Mean σ√(π/2). It is the magnitude of a 2-D Gaussian vector with zero mean.", "Gamma: the sum of independent exponentials (waiting time for several events)."],
    formulas: [["Uniform", "f = 1/(b − a),  E = (a + b)/2,  Var = (b − a)²/12"], ["Exponential", "f = λ e^(−λx),  E = 1/λ,  Var = 1/λ²"], ["Exponential CDF", "F(x) = 1 − e^(−λx)"], ["Memoryless", "P(X > s + t | X > s) = P(X > t)"], ["Rayleigh", "f = (x/σ²) e^(−x²/2σ²),  E = σ √(π/2)"]],
    example: { title: "Bulb lifetime is exponential with mean 1000 hours. Find P(life > 2000 hours).", text: "λ = 1/1000 per hour\nP(X > 2000) = e^(−λ·2000) = e^(−2) = 0.135\nUniform example: X ~ U(0, 10): E = 5, Var = 100/12 = 8.33" },
    exam: "A continuous uniform random variable on (a, b) has f(x) = 1/(b − a), mean (a + b)/2 and variance (b − a)²/12. An exponential random variable with parameter λ has f(x) = λe^(−λx), x ≥ 0, mean 1/λ and variance 1/λ², and it has the memoryless property. The Rayleigh distribution f(x) = (x/σ²)e^(−x²/2σ²) models the envelope of a narrow-band Gaussian noise.",
    mistakes: ["Using λ as the mean of the exponential. The mean is 1/λ.", "Forgetting that the exponential is only for x ≥ 0.", "Mixing up the uniform variance with (b − a)/12."],
    uses: [["Lifetime and reliability", "Time to failure of components."], ["Queues and networks", "Time between packet arrivals."], ["Wireless fading", "Signal strength in a mobile channel follows a Rayleigh model."]], related: ["Gaussian (normal) distribution", "Discrete distributions (Bernoulli, Binomial, Poisson, Geometric)", "Random processes"], diagrams: ["dists3"] },
  { id: "gauss", subject: PRB, keys: ["gaussian distribution", "normal distribution", "gaussian", "normal random variable", "standard normal", "q function", "z score", "standardization", "bell curve", "68 95 99.7 rule", "empirical rule", "erf", "error function", "gaussian noise"], title: "Gaussian (normal) distribution",
    short: "The Gaussian or normal distribution is the bell-shaped distribution defined by its mean μ and variance σ². It is the most important distribution in engineering because noise and sums of many effects are Gaussian.",
    points: ["PDF: f(x) = (1/(σ√(2π))) e^(−(x − μ)²/(2σ²)). It is symmetric about μ and the total area is 1.", "Standard normal: μ = 0 and σ = 1. Standardise any normal variable with Z = (X − μ)/σ.", "Empirical rule: about 68% of values lie within 1σ of the mean, 95% within 2σ and 99.7% within 3σ.", "Φ(z) = P(Z ≤ z) is read from tables. Symmetry: Φ(−z) = 1 − Φ(z). The Q-function is Q(x) = 1 − Φ(x) = P(Z > x), used for bit-error probabilities.", "A linear function of a Gaussian variable is Gaussian. The sum of independent Gaussians is Gaussian with the means and variances added.", "For jointly Gaussian variables, uncorrelated means independent."],
    formulas: [["PDF", "f(x) = (1/(σ√(2π))) e^(−(x − μ)²/(2σ²))"], ["Standardise", "Z = (X − μ) / σ"], ["Symmetry", "Φ(−z) = 1 − Φ(z)"], ["Q-function", "Q(x) = 1 − Φ(x)"], ["Sum", "X + Y ~ N(μ₁ + μ₂, σ₁² + σ₂²)  (independent)"]],
    example: { title: "X ~ N(μ = 50, σ² = 100). Find P(X > 70).", text: "σ = 10\nZ = (70 − 50)/10 = 2\nP(X > 70) = P(Z > 2) = Q(2) = 1 − 0.9772 = 0.0228 (about 2.3%)\nAnd P(40 < X < 60) = P(−1 < Z < 1) = 0.683." },
    exam: "A random variable X is normally distributed with mean μ and variance σ² if its PDF is f(x) = (1/σ√(2π)) exp[−(x − μ)²/2σ²]. The standard normal variable Z = (X − μ)/σ has mean 0 and variance 1. Approximately 68%, 95% and 99.7% of the values lie within one, two and three standard deviations of the mean respectively.",
    mistakes: ["Using the variance instead of the standard deviation when standardising.", "Forgetting symmetry: Φ(−z) = 1 − Φ(z).", "Adding standard deviations instead of variances for a sum of independent Gaussians."],
    uses: [["Thermal noise in receivers", "Noise voltage is modelled as Gaussian."], ["Bit-error rate of digital links", "Error probability uses the Q-function."], ["Measurement errors and exam marks", "Many natural quantities follow a bell curve."]], related: ["Law of large numbers and the central limit theorem", "Expectation, variance and moments", "Random processes"], diagrams: ["bell"] },
  { id: "joint", subject: PRB, keys: ["joint distribution", "joint probability density", "marginal distribution", "covariance", "correlation coefficient", "correlation", "joint pdf", "independent random variables", "uncorrelated", "two random variables", "conditional density", "marginal density", "joint pmf", "bivariate"], title: "Joint distributions, covariance and correlation",
    short: "Joint distributions describe two random variables together. Covariance and the correlation coefficient measure how strongly they move together.",
    points: ["Joint PDF f(x, y) ≥ 0 with a total volume of 1. Marginals: f_X(x) = ∫ f(x, y) dy and f_Y(y) = ∫ f(x, y) dx.", "Conditional PDF: f(x | y) = f(x, y) / f_Y(y).", "X and Y are independent if f(x, y) = f_X(x) f_Y(y) for all x and y. Then E[XY] = E[X]E[Y].", "Covariance: Cov(X, Y) = E[XY] − E[X]E[Y]. Correlation coefficient: ρ = Cov(X, Y) / (σₓ σᵧ), with −1 ≤ ρ ≤ 1.", "Variance of a sum: Var(X + Y) = Var(X) + Var(Y) + 2 Cov(X, Y).", "Independent → uncorrelated (ρ = 0), but uncorrelated does not imply independent (except for jointly Gaussian variables)."],
    formulas: [["Marginal", "f_X(x) = ∫ f(x, y) dy"], ["Conditional", "f(x | y) = f(x, y) / f_Y(y)"], ["Independence", "f(x, y) = f_X(x) f_Y(y)"], ["Covariance", "Cov(X, Y) = E[XY] − E[X] E[Y]"], ["Correlation coefficient", "ρ = Cov(X, Y) / (σₓ σᵧ)"], ["Variance of sum", "Var(X + Y) = Var X + Var Y + 2 Cov(X, Y)"]],
    example: { title: "E[X] = 2, E[Y] = 3, E[XY] = 7, σₓ = 1, σᵧ = 2", text: "Cov(X, Y) = 7 − 2 × 3 = 1\nρ = 1 / (1 × 2) = 0.5\nVar(X + Y) = 1 + 4 + 2 × 1 = 7" },
    exam: "For two random variables X and Y with joint density f(x, y), the marginal densities are f_X(x) = ∫f(x, y)dy and f_Y(y) = ∫f(x, y)dx. X and Y are statistically independent if f(x, y) = f_X(x)f_Y(y). The covariance is Cov(X, Y) = E[XY] − E[X]E[Y] and the correlation coefficient is ρ = Cov(X, Y)/(σₓσᵧ), with |ρ| ≤ 1.",
    mistakes: ["Saying zero correlation always means independence.", "Forgetting the covariance term in Var(X + Y).", "Integrating over the wrong variable to get a marginal."],
    uses: [["Signal and noise together", "Joint behaviour of the signal and the noise at the receiver."], ["Finance and sensors", "How two readings vary together."], ["Image processing", "Neighbouring pixels are strongly correlated."]], related: ["Expectation, variance and moments", "Gaussian (normal) distribution", "Random processes"], diagrams: [] },
  { id: "clt", subject: PRB, keys: ["central limit theorem", "clt", "law of large numbers", "weak law of large numbers", "sample mean", "sampling distribution", "convergence of random variables", "large numbers", "sum of random variables"], title: "Law of large numbers and the central limit theorem",
    short: "The law of large numbers says the average of many trials settles at the true mean. The central limit theorem says the sum or average of many independent variables becomes Gaussian, whatever the original distribution.",
    points: ["Law of large numbers: for independent trials with mean μ, the sample mean X̄ₙ converges to μ as n grows.", "Central limit theorem: for independent identically distributed variables with mean μ and variance σ², the sum Sₙ has mean nμ and variance nσ², and its standardised form approaches N(0, 1) as n → ∞.", "The sample mean has mean μ and variance σ²/n, so its standard deviation σ/√n shrinks as n grows.", "A rule of thumb: n ≥ 30 usually gives a good Gaussian approximation (fewer if the distribution is already symmetric).", "This explains why noise (the sum of many small random effects) is modelled as Gaussian."],
    formulas: [["Sample mean", "X̄ₙ = (X₁ + … + Xₙ) / n"], ["Mean and variance of X̄", "E[X̄] = μ,  Var(X̄) = σ² / n"], ["Standardised sum", "Z = (Sₙ − nμ) / (σ √n) → N(0, 1)"], ["Standard error", "σ / √n"]],
    example: { title: "100 fair dice are rolled. Estimate P(total > 380).", text: "Each die: μ = 3.5, σ² = 35/12 = 2.917\nSum: mean = 350, variance = 291.7, σ = 17.08\nZ = (380 − 350) / 17.08 = 1.76\nP(total > 380) ≈ Q(1.76) = 0.039 (about 4%)" },
    exam: "The central limit theorem states that the distribution of the sum of n independent identically distributed random variables with finite mean μ and variance σ² tends to a Gaussian distribution with mean nμ and variance nσ² as n becomes large. The law of large numbers states that the sample mean converges to the true mean as n → ∞.",
    mistakes: ["Applying the CLT to a few variables or to heavy-tailed variables with infinite variance.", "Using σ instead of σ/√n for the sample mean.", "Confusing the law of large numbers (convergence to the mean) with the CLT (shape of the distribution)."],
    uses: [["Noise modelling in receivers", "Many small effects add up to Gaussian noise."], ["Polling and sampling", "The margin of error shrinks with σ/√n."], ["Simulation", "Averaging more runs gives a more accurate estimate."]], related: ["Gaussian (normal) distribution", "Expectation, variance and moments", "Discrete distributions (Bernoulli, Binomial, Poisson, Geometric)"], diagrams: ["bell"] },
  { id: "rproc", subject: PRB, keys: ["random process", "random processes", "stochastic process", "stationary process", "wide sense stationary", "wss", "autocorrelation", "autocorrelation function", "power spectral density", "psd", "wiener khinchin", "ergodic", "ergodicity", "white noise", "poisson process", "gaussian process", "cross correlation"], title: "Random processes, autocorrelation and power spectral density",
    short: "A random process is a collection of random variables indexed by time, X(t). It describes signals and noise whose exact values cannot be predicted.",
    points: ["Mean: m(t) = E[X(t)]. Autocorrelation: R_X(t₁, t₂) = E[X(t₁) X(t₂)].", "Strict-sense stationary: statistics do not change with a time shift. Wide-sense stationary (WSS): the mean is constant and R depends only on τ = t₁ − t₂.", "WSS properties: R(0) = E[X²] (average power), R(τ) = R(−τ) (even), |R(τ)| ≤ R(0).", "Ergodic: time averages equal ensemble averages, so one long record is enough.", "Power spectral density: S_X(f) = Fourier transform of R_X(τ) (Wiener–Khinchin theorem). The average power is ∫ S_X(f) df = R_X(0).", "White noise: S(f) = N₀/2 for all f, R(τ) = (N₀/2) δ(τ), so different time instants are uncorrelated.", "Through an LTI system with transfer function H(f): S_Y(f) = |H(f)|² S_X(f).", "Poisson process: number of events N(t) in time t with P(N(t) = k) = e^(−λt) (λt)ᵏ / k!."],
    formulas: [["Autocorrelation", "R_X(τ) = E[X(t) X(t + τ)]  (WSS)"], ["Average power", "P = R_X(0) = E[X²]"], ["Wiener–Khinchin", "S_X(f) = ∫ R_X(τ) e^(−j2πfτ) dτ"], ["White noise", "S(f) = N₀/2,  R(τ) = (N₀/2) δ(τ)"], ["Output PSD", "S_Y(f) = |H(f)|² S_X(f)"], ["Poisson process", "P(N(t) = k) = e^(−λt) (λt)ᵏ / k!"]],
    example: { title: "White noise with S(f) = N₀/2 = 10⁻⁹ W/Hz passes through an ideal low-pass filter of bandwidth B = 1 MHz (|f| ≤ B)", text: "Output power = ∫ S_Y(f) df over −B to B\n= (N₀/2) × 2B = 10⁻⁹ × 2 × 10⁶ = 2 × 10⁻³ W (2 mW)" },
    exam: "A random process is a family of random variables X(t). A process is wide-sense stationary if its mean is constant and its autocorrelation depends only on the time difference τ. The power spectral density is the Fourier transform of the autocorrelation function (Wiener–Khinchin theorem), and the average power equals R(0). When a WSS process is applied to an LTI system, the output PSD is SY(f) = |H(f)|² SX(f).",
    mistakes: ["Forgetting that R(0) is the average power, not zero.", "Using |H(f)| instead of |H(f)|² for the PSD.", "Treating a random process as one random variable."],
    uses: [["Receiver noise analysis", "SNR calculations use the noise PSD and filter bandwidth."], ["Speech and audio processing", "Signal statistics are described by autocorrelation."], ["Radar and communication", "Detection of a signal buried in noise."]], related: ["Gaussian (normal) distribution", "Joint distributions, covariance and correlation", "Law of large numbers and the central limit theorem"], diagrams: ["acf"] },
);

